<template>
  <DropdownMenu
    v-bind="$attrs"
    v-on="$listeners"
  >
    <template v-for="(items, groupI) in actions">
      <DropdownMenuDivider
        v-if="groupI"
        :key="`group-${groupI}-divider`"
      />

      <DropdownMenuItem
        v-for="(item, itemI) in items"
        :key="`group-${groupI}-item-${itemI}`"
        :icon="item.icon"
        :label="item.label"
        :disabled="item.disabled"
        @click="item.onClick"
      />
    </template>
  </DropdownMenu>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import type DiagramVm from './Diagram.vue'
import type Diagram from '../diagram'

interface Item {
  icon: string
  label: string
  disabled?: boolean
  onClick: () => void
}

export const getActions = (diagramVm: DiagramVm) => {
  const { diagram } = diagramVm

  const group1: Item[] = []
  const group2: Item[] = []

  let showTaxiToggle = false

  for (const layout of diagram.layouts) {
    group1.push({
      get icon () { return layout === diagram.activeDiagram.settings.activeLayout ? 'check' : ' ' },
      label: layout.name,
      onClick: () => diagram.eventBus.emit({ name: 'graph.layout', layout }),
    })

    if (layout.enableTaxiToggle) showTaxiToggle = true
  }

  if (showTaxiToggle) {
    group2.push({
      label: 'Knækpile',
      get icon () { return diagram.activeDiagram.settings.enableTaxi ? 'check' : ' ' },
      get disabled () { return !diagram.activeDiagram.settings.activeLayout?.enableTaxiToggle },
      onClick: () => {
        diagram.activeDiagram.settings.setEnableTaxi(!diagram.activeDiagram.settings.enableTaxi)
        diagram.eventBus.emit({ name: 'settingsChanged' })
        diagram.eventBus.emit({ name: 'dataUpdated' })
        diagram.eventBus.emit({ name: 'graph.spreadTaxiEdges' })
      },
    })
  }

  return [
    group1,
    group2,
  ].filter(items => items.length)
}

@Component({
  components: {
    DropdownMenu,
    DropdownMenuItem,
    DropdownMenuDivider,
  },

  inheritAttrs: false,
})

export default class LayoutDropdownMenu extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly diagramVm!: DiagramVm

  get actions () {
    return getActions(this.diagramVm)
  }
}
</script>
