<template>
  <div class="lassox-diagram__TopBar">
    <ButtonGroup style="padding-right: 16px">
      <Button
        class="lassox-diagram__TopBar_print-button"
        type="primary"
        label="Udskriv"
        @click="() => diagram.store.showPrintDialog('print')"
      />

      <Button
        ref="saveAsDropdownButton"
        class="lassox-diagram__TopBar_save-as-button"
        label="Gem som"
        :trailingIcon="showSaveAsDropdownMenu ? 'expand_less' : 'expand_more'"
        @click="() => showSaveAsDropdownMenu = !showSaveAsDropdownMenu"
      />

      <Button
        v-if="diagram.enableDocuments"
        class="lassox-diagram__TopBar_load-button"
        label="Indlæs"
        @click="() => diagram.store.showLoadDialog()"
      />
    </ButtonGroup>

    <div
      v-if="(
        (!compact || true)
        && (
          (diagram.activeDiagram.id && diagram.activeDiagram.title || diagram.enableSharing)
          || (diagram.enableSaving && diagram.hasUnsavedChanges)
        )
      )"
      class="lassox-diagram__TopBar_active-diagram"
      style="padding-right: 16px"
    >
      <template v-if="diagram.activeDiagram.id">
        <div
          v-if="diagram.activeDiagram.title"
          class="lassox-diagram__TopBar_active-diagram-name"
          v-text="diagram.activeDiagram.title"
        />

        <div
          v-if="diagram.activeDiagram.title && diagram.enableSharing"
          style="width: 12px; flex-shrink: 0"
        />

        <IconButton
          v-if="diagram.enableSharing"
          class="lassox-diagram__TopBar_active-diagram-shared-icon"
          :icon="diagram.activeDiagram.shared ? 'lock_open' : 'lock'"
          v-tooltip="diagram.activeDiagram.shared ? 'Diagrammet er delt med din organisation' : 'Diagrammet er privat og deles ikke'"
          @click="() => diagram.enableDocuments && showEditDiagramDialog()"
        />

        <div
          v-if="(diagram.activeDiagram.title || diagram.enableSharing) && diagram.hasUnsavedChanges"
          style="width: 12px; flex-shrink: 0"
        />
      </template>

      <div
        v-if="diagram.enableSaving && diagram.hasUnsavedChanges"
        class="lassox-diagram__TopBar_active-diagram-unsaved-changes"
      >
        <div
          v-if="diagram.activeDiagram.id && (diagram.activeDiagram.title || diagram.enableSharing)"
          style="margin-right: 12px"
        >&mdash;</div>

        <div
          v-if="diagram.isSaving"
          v-text="'Gemmer...'"
        />

        <a
          v-else
          class="lassox-diagram__TopBar_active-diagram-unsaved-changes-link"
          href="#"
          v-text="'Gem ændringer'"
          @click.prevent="() => {
            if (!diagram.activeDiagram.id && diagram.enableDocuments) showSaveDialog()
            else save()
          }"
        />
      </div>
    </div>

    <ButtonGroup style="margin-left: auto">
      <div
        v-if="diagram.updater.enabled"
        ref="updateButtonEl"
        class="lassox-diagram__TopBar-update-button"
      >
        <Button
          icon="sync"
          v-tooltip="updater.buttonTooltip"
          @mouseenter="() => showUpdatesAvailableTooltip = false"
          @click="showSyncDialog"
        />

        <div
          class="lassox-diagram__TopBar-update-button-dot"
          :class="[
            'lassox-diagram__TopBar-update-button-dot',
            updater.loaded && 'lassox-diagram__TopBar-update-button-dot--loaded'
          ]"
          :style="{ opacity: updater.showButtonDot ? 1 : 0 }"
          v-text="updater.loaded ? updater.countString : ''"
        />

        <Tooltip
          :el="updateButtonEl"
          :overrideShow="showUpdatesAvailableTooltip"
          text="Der er opdateringer til diagrammet"
        />
      </div>

      <Button
        v-if="diagram.methods.openFullscreen"
        class="lassox-diagram__TopBar_fullscreen-button"
        icon="fullscreen"
        v-tooltip="'Vis i fuld skærm'"
        @click="diagram.methods.openFullscreen"
      />

      <Button
        v-if="diagram.layouts.length"
        class="lassox-diagram__TopBar_layout-button"
        ref="layoutDropdownButton"
        label="Layout"
        :trailingIcon="showLayoutDropdownMenu ? 'expand_less' : 'expand_more'"
        @click="() => showLayoutDropdownMenu = !showLayoutDropdownMenu"
      />

      <Button
        v-if="diagram.enableExpand"
        class="lassox-diagram__TopBar_expand-button"
        label="Udvid alle"
        :disabled="diagram.activeDiagram.expanding"
        @click="() => diagram.activeDiagram.expand()"
      />

      <Button
        ref="editDropdownButton"
        class="lassox-diagram__TopBar_edit-button"
        label="Rediger"
        :trailingIcon="showEditDropdownMenu ? 'expand_less' : 'expand_more'"
        @click="() => showEditDropdownMenu = !showEditDropdownMenu"
      />

      <Button
        v-if="compact"
        class="lassox-diagram__TopBar_fit-button"
        label="Tilpas"
        @mousedown="e => {
          if (diagramVm.showCustomizer) e.preventDefault()
        }"
        @click="() => {
          diagramVm.showCustomizer = !diagramVm.showCustomizer
        }"
      />
    </ButtonGroup>

    <!-- Save as dropdown -->
    <DropdownMenu
      :opener="showSaveAsDropdownMenu ? $refs.saveAsDropdownButton.$el : null"
      :close="() => showSaveAsDropdownMenu = false"
    >
      <template v-if="diagram.enableSaving && diagram.enableDocuments">
        <DropdownMenuItem
          label="Nyt diagram"
          @click="() => showSaveDialog()"
        />

        <DropdownMenuDivider />
      </template>

      <DropdownMenuItem
        v-if="diagram.methods.convertPngToPdf"
        label="PDF"
        @click="() => diagram.store.showPrintDialog('pdf')"
      />

      <DropdownMenuItem
        label="Billede"
        @click="() => diagram.store.showPrintDialog('png')"
      />
    </DropdownMenu>

    <!-- Layouts dropdown -->
    <LayoutDropdownMenu
      v-if="diagram.layouts.length"
      :opener="showLayoutDropdownMenu ? $refs.layoutDropdownButton.$el : null"
      :close="() => showLayoutDropdownMenu = false"
    />

    <!-- Edit dropdown -->
    <DropdownMenu
      :opener="showEditDropdownMenu ? $refs.editDropdownButton.$el : null"
      :close="() => showEditDropdownMenu = false"
    >
      <template v-if="diagram.enableEditing">
        <DropdownMenuItem
          label="Tilføj"
          icon="add"
          @click="showAddDialog"
        />

        <DropdownMenuDivider />
      </template>

      <DropdownMenuItem
        label="Fortryd"
        icon="undo"
        :disabled="!canUndo"
        @click="undo"
      />

      <DropdownMenuItem
        label="Annuller fortryd"
        icon="redo"
        :disabled="!canRedo"
        @click="redo"
      />

      <DropdownMenuItem
        label="Nulstil"
        icon="replay"
        :disabled="!canUndo"
        @click="reset"
      />

      <template v-if="diagram.activeDiagram.id && ((diagram.enableSaving && diagram.enableDocuments) || diagram.methods.deleteSavedDiagram)">
        <DropdownMenuDivider />

        <DropdownMenuItem
          v-if="diagram.enableSaving && diagram.enableDocuments"
          label="Rediger diagram"
          icon="edit"
          @click="() => showEditDiagramDialog()"
        />

        <DropdownMenuItem
          v-if="diagram.methods.deleteSavedDiagram"
          label="Slet"
          icon="delete"
          @click="() => showConfirmDeleteDiagramDialog()"
        />
      </template>
    </DropdownMenu>
  </div>
</template>

<script lang="ts">
import { Component, Inject, Ref } from 'vue-property-decorator'
import DiagramVue from '../DiagramVue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import IconButton from './IconButton.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import LayoutDropdownMenu from './LayoutDropdownMenu.vue'
import Tooltip from './Tooltip.vue'
import type DiagramVm from './Diagram.vue'
import type { default as Diagram } from '../diagram'
import ConfirmResetDialog from './ConfirmResetDialog.vue'
import AddEntityDialog from './AddEntityDialog.vue'
import EditDiagramDialog from './EditDiagramDialog.vue'
import ConfirmDeleteDiagramDialog from './ConfirmDeleteDiagramDialog.vue'
import SyncDialog from './SyncDialog.vue'

@Component({
  components: {
    ButtonGroup,
    Button,
    IconButton,
    DropdownMenu,
    DropdownMenuItem,
    DropdownMenuDivider,
    LayoutDropdownMenu,
    Tooltip,
  },
})

export default class TopBar extends DiagramVue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  @Ref()
  readonly updateButtonEl?: HTMLElement

  showSaveAsDropdownMenu = false
  showLoadDropdownMenu = false
  showLayoutDropdownMenu = false
  showEditDropdownMenu = false
  showUpdatesAvailableTooltip = false

  get compact () {
    return this.diagramVm.compact
  }

  get updater () {
    const vm = this

    return {
      get loaded () { return vm.diagram.activeDiagram.updater.loaded },
      get count () { return vm.diagram.activeDiagram.updater.defaultCheckedUpdateCount },
      get countString () { return this.count > 9 ? '9+' : this.count.toString() },
      get showButtonDot () { return this.loaded ? !!this.count : !!vm.diagram.activeDiagram.id },
      get buttonTooltip () {
        if (vm.showUpdatesAvailableTooltip) return null
        if (!this.loaded) return 'Tjek efter opdateringer'
        return this.count ? 'Opdater diagram' : 'Ingen opdateringer'
      },
    }
  }

  get canUndo () {
    return this.diagram.activeDiagram.data.canUndo
  }

  get canRedo () {
    return this.diagram.activeDiagram.data.canRedo
  }

  created () {
    let hasShownUpdatesAvailable = false

    this.$watch(
      () => this.diagram.activeDiagram,
      () => hasShownUpdatesAvailable = false,
      { immediate: true },
    )

    this.$watch(
      () => [ this.diagram.activeDiagram, this.diagram.activeDiagram.updater.defaultCheckedUpdateCount ],
      ([ , updateCount ]) => {
        if (!updateCount) {
          this.showUpdatesAvailableTooltip = false
          return
        }

        if (hasShownUpdatesAvailable) return

        const activeDiagram = this.diagram.activeDiagram
        hasShownUpdatesAvailable = true
        this.showUpdatesAvailableTooltip = true

        setTimeout(() => {
          if (this.diagram.activeDiagram !== activeDiagram) return
          this.showUpdatesAvailableTooltip = false
        }, 5000)
      },
      { immediate: true },
    )
  }

  async save (overwrite = true) {
    const closeLoadingToast = this.diagram.store.showToast({
      content: 'Gemmer diagrammet...',
      dismissable: false,
      duration: 0,
      showLoadingSpinner: true,
    })

    try {
      await this.diagram.save(overwrite)
      closeLoadingToast()
      this.diagram.store.showToast({ content: 'Diagrammet blev gemt, og du kan nu redigere videre på det.' })
    } catch (error) {
      console.error('Failed to save diagram', error)
      closeLoadingToast()
      this.diagram.store.showToast({ content: 'Noget gik galt.' })
    }
  }

  undo () {
    this.diagram.activeDiagram.data.undo()
  }

  redo () {
    this.diagram.activeDiagram.data.redo()
  }

  reset () {
    this.diagram.store.showDialog(ConfirmResetDialog, {
      onConfirm: () => this.diagram.reset(),
    })
  }

  showAddDialog () {
    this.diagram.store.showDialog(AddEntityDialog)
  }

  showSaveDialog () {
    this.diagram.store.showDialog(EditDiagramDialog, {
      title: 'Gem diagram',
      ignoreOwnership: true,
      save: async (fields: { title: string, description: string, shared: boolean }) => {
        this.diagram.activeDiagram.title = fields.title
        this.diagram.activeDiagram.description = fields.description
        this.diagram.activeDiagram.shared = fields.shared
        await this.diagram.save(false)
      },
    })
  }

  showSyncDialog () {
    if (
      this.diagram.activeDiagram.updater.loaded
      && !this.diagram.activeDiagram.updater.updateCount
    ) return

    this.diagram.store.showDialog(SyncDialog)
  }

  showEditDiagramDialog () {
    this.diagram.store.showDialog(EditDiagramDialog, {
      save: (fields: { title: string, description: string, shared: boolean }) => {
        this.diagram.activeDiagram.title = fields.title
        this.diagram.activeDiagram.description = fields.description
        this.diagram.activeDiagram.shared = fields.shared
        this.diagram.hasUnsavedChanges = true
      },
    })
  }

  showConfirmDeleteDiagramDialog () {
    this.diagram.store.showDialog(ConfirmDeleteDiagramDialog)
  }
}
</script>

<style lang="scss">
.lassox-diagram__TopBar {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  flex-grow: 0;
  padding: 12px 16px;
  padding-bottom: 12px + 1px;
  background-color: white;
  box-shadow: inset 0 -1px 0 0 rgba(black, 0.12);
  overflow-x: auto;

  & > .lassox-diagram__ButtonGroup {
    flex-shrink: 0;
  }

  &_active-diagram {
    display: flex;
    align-items: center;
    min-width: 0;
    flex-shrink: 0;

    &-name,
    &-unsaved-changes {
      white-space: nowrap;
    }

    &-name {
      min-width: 32px;
      flex-shrink: 1;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    &-unsaved-changes {
      display: flex;
      align-items: center;
      flex-shrink: 0;
    }
  }

  &-update-button {
    position: relative;

    &-dot {
      position: absolute;
      z-index: 1;
      top: 1px;
      right: 1px;
      min-width: 16px;
      height: 16px;
      padding: 0 4px;
      color: white;
      font-size: 10px;
      line-height: 16px;
      font-weight: 500;
      text-align: center;
      border-radius: 8px;
      background-color: #ffa07a;
      box-shadow: 0 2px 5px 0 rgba(black, 0.1);
      transform: translate(50%, -50%) scale(0.75);
      pointer-events: none;
      transition: transform 100ms, opacity 100ms;

      &--loaded {
        transform: translate(50%, -50%) scale(1);
      }
    }
  }
}
</style>
