<template>
  <div
    :class="[
      'lassox-diagram__IconButton',
      light && 'lassox-diagram__IconButton--light',
    ]"
    :style="{
      width: `${finalIconSize}px`,
      height: `${finalIconSize}px`,
    }"
  >
    <BaseButton
      class="lassox-diagram__IconButton_button"
      :style="{
        width: `${finalButtonSize}px`,
        height: `${finalButtonSize}px`,
      }"
      v-on="$listeners"
    >
      <Icon
        class="lassox-diagram__IconButton_button-icon"
        :icon="icon"
        :size="finalIconSize"
        :light="light"
      />
    </BaseButton>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'
import Icon from './Icon.vue'

const sizes = {
  small: {
    iconSize: 18,
    buttonSize: 32,
  },
  normal: {
    iconSize: 24,
    buttonSize: 40,
  },
}

@Component({
  components: {
    BaseButton,
    Icon,
  },
})

export default class IconButton extends Vue {
  @Prop({ type: String, required: true })
  readonly icon!: string

  @Prop({ type: String, default: 'small', validator: (preset: string) => preset in sizes })
  readonly size!: keyof typeof sizes

  @Prop({ type: Number })
  readonly iconSize?: number

  @Prop({ type: Number })
  readonly buttonSize?: number

  @Prop({ type: Boolean, default: false })
  readonly light!: boolean

  get finalSize () {
    return sizes[this.size]
  }

  get finalIconSize () {
    return this.iconSize ?? this.finalSize.iconSize
  }

  get finalButtonSize () {
    return this.buttonSize ?? this.finalSize.buttonSize
  }
}
</script>

<style lang="scss">
.lassox-diagram__IconButton {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-grow: 0;
  flex-shrink: 0;

  &_button {
    flex-grow: 0;
    flex-shrink: 0;
    border-radius: 50%;

    &-icon {
      margin: auto;
    }
  }

  &--light &_button .lassox-diagram__BaseButton_overlay {
    background-color: rgba(white, 0.16);
  }
}
</style>
