<template>
  <div
    :class="[
      'lassox-diagram__Graph',
      elementHovered && 'lassox-diagram__Graph--has-hovered-element',
    ]"
    :tabindex="printMode ? '' : '-1'"
    @keydown="onKeyDown"
    @contextmenu.prevent="() => {}"
  >
    <div
      class="lassox-diagram__Graph-scaler"
      :style="{
        width: `${scaling * 100}%`,
        height: `${scaling * 100}%`,
        transform: `scale(${1 / scaling})`,
      }"
    >
      <div
        ref="graphContainerEl"
        class="lassox-diagram__Graph-container"
        style="width: 100%; height: 100%"
        @mousedown="redirectCytoscapeBlur"
        @touchstart="redirectCytoscapeBlur"
      >
        <div
          ref="graphNodesEl"
          class="lassox-diagram__Graph-nodes"
        >
          <GraphEdge
            v-for="relation in relations"
            :key="relation.id"
            :id="relation.id"
          />

          <GraphNode
            v-for="entity in entities"
            :key="entity.id"
            :id="entity.id"
          />

          <GraphEdgePoints v-if="!printMode && diagram.enableTaxiEditing && graphReady" />
        </div>
      </div>
    </div>

    <GraphContextMenu v-if="!printMode" />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Ref, Inject, Provide } from 'vue-property-decorator'
import { Entity, LayoutDefinition, Relation, createContextItem, CustomTaxi } from '../diagram'
import cytoscape from 'cytoscape'
import panzoom from 'cytoscape-panzoom'
import 'cytoscape-panzoom/cytoscape.js-panzoom.css'
import dagre from 'cytoscape-dagre'
import GraphNode from './GraphNode.vue'
import GraphEdge from './GraphEdge.vue'
import GraphEdgePoints from './GraphEdgePoints.vue'
import GraphContextMenu from './GraphContextMenu.vue'
import { watchRect } from '../util/watch-rect'
import type { EntityMove } from '../types/DiagramData'
import type DiagramVm from './Diagram.vue'
import cloneDeep from 'lodash.clonedeep'

const generateStyle = (vm: Graph): cytoscape.Stylesheet[] => {
  const getStyle = (element: cytoscape.NodeSingular | cytoscape.EdgeSingular, property: string) => {
    const item = element.isNode() ? element.data('entity') : element.data('relation')
    return (vm.printMode ? item.builtPrintStyle : item.builtPreviewStyle || item.builtStyle)[property]
  }

  const getEdgeWidth = (edge: cytoscape.EdgeSingular): number => getStyle(edge, 'lineWidth')

  const getEdgeColor = (edge: cytoscape.EdgeSingular) => (
    (!vm.printMode && edge.selected()) ? '#ffa07a' :
    getStyle(edge, 'lineColor')
  )

  return [
    {
      selector: 'node',
      style: {
        'width': (node: cytoscape.NodeSingular) => node.data('width'),
        'height': (node: cytoscape.NodeSingular) => node.data('height'),

        'background-opacity': 0,
        'shape': 'rectangle',
      },
    },

    {
      selector: 'edge',
      style: {
        'z-index': (edge: cytoscape.EdgeSingular) => (!vm.printMode && edge.selected()) ? 1 : 0,

        'width': getEdgeWidth,

        'curve-style': edge => getStyle(edge, 'taxi') ? 'taxi' : 'bezier',

        'line-color': getEdgeColor,
        'source-arrow-color': getEdgeColor,
        'target-arrow-color': getEdgeColor,
        'source-arrow-fill': 'filled',
        'target-arrow-fill': 'filled',
        'arrow-scale': edge => getStyle(edge, 'arrowSize') / getEdgeWidth(edge),

        'line-style': edge => getStyle(edge, 'lineStyle') === 'solid' ? 'solid' : 'dashed',

        "line-dash-pattern": ((edge: any) => {
          const width = getEdgeWidth(edge)
          return getStyle(edge, 'lineStyle') === 'dotted' ? [width, width * 2] : [width * 2, width]
        }) as any,

        'source-arrow-shape': edge => getStyle(edge, 'arrowFrom') ? 'triangle-backcurve' : 'none',
        'target-arrow-shape': edge => getStyle(edge, 'arrowTo') ? 'triangle-backcurve' : 'none',

        'control-point-step-size': () => 100,

        // These don't exist in cytoscapes ts definitions
        ...{
          'loop-direction': () => '30deg',
          'loop-sweep': () => '45deg',
        },
      },
    },

    {
      selector: 'edge[?customPath]',
      style: {
        'curve-style': 'segments',
        'source-endpoint': edge => edge.data('customPath').sourceEndpoint,
        'target-endpoint': edge => edge.data('customPath').targetEndpoint,
        'edge-distances': 'node-position',
        'segment-distances': edge => edge.data('customPath').segmentDistances,
        'segment-weights': edge => edge.data('customPath').segmentWeights,
      },
    },

    {
      selector: 'edge[?builtCustomTaxi]',
      style: {
        'curve-style': 'segments',
        'source-endpoint': edge => edge.data('builtCustomTaxi').sourceEndpoint,
        'target-endpoint': edge => edge.data('builtCustomTaxi').targetEndpoint,
        'edge-distances': 'node-position',
        'segment-distances': edge => edge.data('builtCustomTaxi').segmentDistances,
        'segment-weights': edge => edge.data('builtCustomTaxi').segmentWeights,
      },
    },

    {
      selector: '[?hidden], [?hiddenByFilter]',
      style: { 'visibility': 'hidden' },
    },
  ]
}

function getDistWeight (source: cytoscape.Position, target: cytoscape.Position, point: cytoscape.Position) {
  const getDistance = (a: cytoscape.Position, b: cytoscape.Position) => {
    const x = b.x - a.x
    const y = b.y - a.y
    return Math.sqrt(x * x + y * y)
  }

  function getRadAngle (a: cytoscape.Position, b: cytoscape.Position) {
    return Math.atan2(b.y - a.y, b.x - a.x)
  }

  const lineAngle = getRadAngle(source, target)
  const pointAngle = getRadAngle(source, point)
  const angleDiff = pointAngle - lineAngle

  const lineLength = getDistance(source, target)
  const pointDistance = getDistance(source, point)

  const distMult = Math.sin(angleDiff)
  const distance = pointDistance * distMult

  const weightMult = Math.cos(angleDiff)
  const weight = (pointDistance * weightMult) / lineLength

  return {
    distance,
    weight,
  }
}

const safePrecision = (number: number) => {
  const mag = Math.pow(10, 2)
  return Math.round(number * mag) / mag
}

function spreadTaxiEdges (graph: cytoscape.Core) {
  const sanitizePosition = ({ x, y }: cytoscape.Position) => ({
    x: safePrecision(x),
    y: safePrecision(y),
  })

  const sanitizePositions = (positions: cytoscape.Position[]) => positions.map(sanitizePosition)

  type Sides = Record<'top' | 'left' | 'right' | 'bottom', Side>

  type Side = { edges: SideEdge[] }

  type SideEdge = {
    edge: cytoscape.EdgeSingular
    xDist: number
    yDist: number
  }

  const nodeMap = new Map<cytoscape.NodeSingular, {
    node: cytoscape.NodeSingular
    sides: Sides
  }>()

  const edgeMap = new Map<cytoscape.EdgeSingular, {
    edge: cytoscape.EdgeSingular
    newSourceEndpoint: cytoscape.Position
    newTargetEndpoint: cytoscape.Position
    newSourceEndpointOffset: cytoscape.Position
    newTargetEndpointOffset: cytoscape.Position
    newSegmentPoints: cytoscape.Position[]
  }>()

  const getMapEdge = (edge: cytoscape.EdgeSingular) => {
    let mapEdge = edgeMap.get(edge)
    if (!mapEdge) {
      const sourceEndpoint = edge.sourceEndpoint()
      const targetEndpoint = edge.targetEndpoint()

      for (const pos of [ sourceEndpoint, targetEndpoint ]) {
        for (const axis of [ 'x', 'y' ] as const) {
          if (isNaN(pos[axis])) return null
        }
      }

      mapEdge = {
        edge,
        newSourceEndpoint: sourceEndpoint,
        newTargetEndpoint: targetEndpoint,
        newSourceEndpointOffset: { x: 0, y: 0 },
        newTargetEndpointOffset: { x: 0, y: 0 },
        newSegmentPoints: sanitizePositions(edge.segmentPoints()),
      }

      edgeMap.set(edge, mapEdge)
    }
    return mapEdge
  }

  graph.batch(() => {
    const nodes = graph.nodes('[!hiddenByFilter]').toArray()

    for (const node of nodes) {
      const edges = node.connectedEdges(':simple[!hiddenByFilter][!builtCustomTaxi]')
        .toArray()
        .filter(edge => edge.style('curve-style') === 'taxi')

      if (!edges.length) continue

      const width = safePrecision(node.width())
      const height = safePrecision(node.height())

      const centerPos = sanitizePosition(node.position())

      const topPos = safePrecision(centerPos.y - height / 2)
      const bottomPos = safePrecision(centerPos.y + height / 2)
      const leftPos = safePrecision(centerPos.x - width / 2)
      const rightPos = safePrecision(centerPos.x + width / 2)

      const sides: Sides = {
        top: { edges: [] },
        left: { edges: [] },
        right: { edges: [] },
        bottom: { edges: [] },
      }

      // Split edges by which side of node they come from
      for (const edge of edges) {
        const mapEdge = getMapEdge(edge)

        if (!mapEdge) continue

        const endpoints = [ mapEdge.newSourceEndpoint, mapEdge.newTargetEndpoint ]

        if (edge.source() !== node) endpoints.reverse()

        const [ endpoint, oppositeEndpoint ] = endpoints

        let side = sides.top

        if (endpoint.y - 1 <= topPos) side = sides.top
        else if (endpoint.y + 1 >= bottomPos) side = sides.bottom
        else if (endpoint.x - 1 <= leftPos) side = sides.left
        else if (endpoint.x + 1 >= rightPos) side = sides.right

        side.edges.push({
          edge,
          xDist: safePrecision(oppositeEndpoint.x - endpoint.x),
          yDist: safePrecision(oppositeEndpoint.y - endpoint.y),
        })
      }

      // Sort edges for each side based on opposite endpoint position
      for (const sideName of [ 'top', 'left', 'right', 'bottom' ] as const) {
        const side = sides[sideName]

        const compareYDist = (a: SideEdge, b: SideEdge) => (
          a.yDist === b.yDist
            ? 0
            : a.yDist < b.yDist
              ? -1
              : 1
        )

        const compareXDist = (a: SideEdge, b: SideEdge) => (
          a.xDist === b.xDist
            ? 0
            : a.xDist < b.xDist
              ? -1
              : 1
        )

        const compareArrows = (a: SideEdge, b: SideEdge) => {
          const getScore = ({ edge }: SideEdge) => {
            const relation: Relation = edge.data('relation')
            const arrows = [ relation.builtStyle.arrowFrom, relation.builtStyle.arrowTo ]
            if (edge.source() === node) arrows.reverse()
            if (arrows[0] && arrows[1]) return 3
            if (arrows[0]) return 2
            if (arrows[1]) return 1
            return 0
          }

          return getScore(a) - getScore(b)
        }

        side.edges.sort((a, b) => {
          let xScore = compareXDist(a, b)
          let yScore = compareYDist(a, b)

          switch (sideName) {
            case 'top':
            case 'bottom': {
              if (sideName === 'bottom') yScore *= -1
              if (xScore === 0 && a.xDist < 0) yScore *= -1
              if (xScore || yScore) return xScore || yScore
              break
            }

            case 'left':
            case 'right': {
              if (sideName === 'right') xScore *= -1
              if (yScore === 0 && a.yDist < 0) xScore *= -1
              if (xScore || yScore) return yScore || xScore
              break
            }
          }

          return compareArrows(a, b)
        })
      }

      nodeMap.set(node, { node, sides })

      // Calculate new endpoints and segment points
      for (const sideName of [ 'top', 'left', 'right', 'bottom' ] as const) {
        const side = sides[sideName]
        const axis = (sideName === 'left' || sideName === 'right') ? 'x' : 'y'
        const crossAxis = axis === 'x' ? 'y' : 'x'

        const isVertical = sideName === 'top' || sideName === 'bottom'

        const range = 100
        const interval = range / (side.edges.length + 1)
        const min = -50 + (100 - range) / 2

        for (const [ index, { edge } ] of side.edges.entries()) {
          const mapEdge = getMapEdge(edge)

          if (!mapEdge) continue

          const isSource = edge.source() === node

          const mapEdgeEndpoint = mapEdge[isSource ? 'newSourceEndpoint' : 'newTargetEndpoint']
          const mapEdgeEndpointOffset = mapEdge[isSource ? 'newSourceEndpointOffset' : 'newTargetEndpointOffset']

          const value = min + interval * (index + 1)
          const delta = (isVertical ? node.width() : node.height()) * (value / 100)

          mapEdgeEndpointOffset[axis] = (sideName === 'top' || sideName === 'left') ? -0.5 : 0.5
          mapEdgeEndpointOffset[crossAxis] = value / 100

          const midpoint = {
            x: (mapEdge.newSourceEndpoint.x + mapEdge.newTargetEndpoint.x) / 2,
            y: (mapEdge.newSourceEndpoint.y + mapEdge.newTargetEndpoint.y) / 2,
          }

          if (isVertical) {
            mapEdgeEndpoint.x += delta

            mapEdge.newSegmentPoints = [
              { x: mapEdge.newSourceEndpoint.x, y: midpoint.y },
              { x: mapEdge.newTargetEndpoint.x, y: midpoint.y },
            ]
          } else {
            mapEdgeEndpoint.y += delta

            mapEdge.newSegmentPoints = [
              { x: midpoint.x, y: mapEdge.newSourceEndpoint.y },
              { x: midpoint.x, y: mapEdge.newTargetEndpoint.y },
            ]
          }
        }
      }
    }

    // Apply new endpoints and segments
    for (const { edge, newSourceEndpointOffset, newTargetEndpointOffset, newSegmentPoints } of edgeMap.values()) {
      const source = edge.source().position()
      const target = edge.target().position()

      const segmentDistances: number[] = []
      const segmentWeights: number[] = []

      for (const point of newSegmentPoints) {
        const { distance, weight } = getDistWeight(source, target, point)
        segmentDistances.push(distance)
        segmentWeights.push(weight)
      }

      edge.data('customPath', {
        sourceEndpoint: `${newSourceEndpointOffset.x * 100}% ${newSourceEndpointOffset.y * 100}%`,
        targetEndpoint: `${newTargetEndpointOffset.x * 100}% ${newTargetEndpointOffset.y * 100}%`,
        segmentDistances,
        segmentWeights,
      })
    }
  })
}

panzoom(cytoscape)
cytoscape.use(dagre)

@Component({
  components: {
    GraphNode,
    GraphEdge,
    GraphEdgePoints,
    GraphContextMenu,
  },
})

export default class Graph extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Provide()
  get graphVm () {
    return this
  }

  @Prop({ type: Boolean, default: true })
  readonly zoom!: boolean

  @Prop({ type: Boolean, default: false })
  readonly printMode!: boolean

  @Prop({ type: Number, default: 1 })
  readonly scaling!: number

  @Ref()
  readonly graphContainerEl!: HTMLElement

  @Ref()
  readonly graphNodesEl!: HTMLElement

  rect = {
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    width: 0,
    height: 0,
  }

  _graph?: cytoscape.Core
  graphReady = false

  animating = false

  addedItems = new Map<string, Entity | Relation>()
  entities: Entity[] = []
  relations: Relation[] = []
  elementHovered = false

  _editorTarget: cytoscape.NodeSingular | cytoscape.EdgeSingular | null = null

  contextMenu: {
    show: boolean
    position: cytoscape.Position
    modelPosition: cytoscape.Position
    selectedItems: (Entity | Relation)[]
  } = {
    show: false,
    position: { x: 0, y: 0 },
    modelPosition: { x: 0, y: 0},
    selectedItems: [],
  }

  // focusPanZoom: {
  //   stateBefore: {
  //     pan: cytoscape.Position
  //     zoom: number
  //   } | null
  // } = {
  //   stateBefore: null,
  // }

  destroyCallbacks: (() => void)[] = []

  get diagram () {
    return this.diagramVm.diagram
  }

  get editor () {
    return this.diagramVm.editorVue
  }

  get el () {
    return this.$el as HTMLElement
  }

  get fitPadding () {
    // return this.printMode ? 16 * 4 : 16
    return 16 * this.scaling
  }

  mounted () {
    this.destroyCallbacks.push(watchRect(this.el, this.onResize).unwatch)

    this.initialize()

    const graph = this._graph
    if (!graph) return

    const smoothPanZoom = (() => {
      const duration = 500

      let stop: (() => void) | null = null

      const smoothPanZoom = (pan?: cytoscape.Position, zoom?: number) => {
        stop?.()

        if (pan === undefined && zoom === undefined) return

        const startTime = performance.now()

        const from = {
          pan: { ...graph.pan() },
          zoom: graph.zoom(),
        }

        const to = {
          pan: { ...from.pan },
          zoom: from.zoom,
        }

        let shouldPan = false
        let shouldZoom = false

        if (pan !== undefined) {
          to.pan = { ...pan }
          shouldPan = true
        }

        if (zoom !== undefined) {
          to.zoom = zoom
          shouldZoom = true
        }

        const delta = {
          pan: {
            x: to.pan.x - from.pan.x,
            y: to.pan.y - from.pan.y,
          },
          zoom: to.zoom - from.zoom,
        }

        this.animating = true
        if (this.zoom) {
          graph.userPanningEnabled(false)
          graph.userZoomingEnabled(false)
        }
        // const ease = (t: number) => t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2
        // const ease = (t: number) => t === 1 ? 1 : 1 - Math.pow(2, -10 * t)
        const ease = (t: number) => 1 - Math.pow(1 - t, 3)

        const doFrame = () => {
          const timePassed = performance.now() - startTime
          const t = Math.min(timePassed / duration, 1)
          const n = ease(t)

          const pan = shouldPan ? {
            x: from.pan.x + delta.pan.x * n,
            y: from.pan.y + delta.pan.y * n,
          } : to.pan

          const zoom = shouldZoom ? from.zoom + delta.zoom * n : to.zoom

          graph.viewport({ pan, zoom })

          if (n === 1) {
            this.animating = false
            if (this.zoom) {
              graph.userPanningEnabled(true)
              graph.userZoomingEnabled(true)
            }
            return
          }

          rafId = requestAnimationFrame(doFrame)
        }

        let rafId = requestAnimationFrame(doFrame)

        stop = () => cancelAnimationFrame(rafId)
      }

      return smoothPanZoom
    })()

    const smoothPanZoomToElement = (element: cytoscape.SingularElementArgument) => {
      let editorOverlap = 0
      if (this.editor?.el) {
        editorOverlap = Math.max(0, this.rect.right - this.editor.rect.left)
        if (editorOverlap >= this.rect.width) editorOverlap = 0
      }

      const graphWidth = this.rect.width - editorOverlap
      const graphHeight = this.rect.height

      const padding = 32

      const bbox = { ...element.boundingBox({}) }

      const x = bbox.x1 + bbox.w / 2
      const y = bbox.y1 + bbox.h / 2

      bbox.x1 -= padding
      bbox.x2 += padding
      bbox.w += padding * 2

      bbox.y1 -= padding
      bbox.y2 += padding
      bbox.h += padding * 2

      const zoomX = graphWidth / bbox.w
      const zoomY = graphHeight / bbox.h
      const zoom = Math.min(1, zoomX, zoomY)

      const pan = {
        x: -x * zoom + graphWidth / 2,
        y: -y * zoom + graphHeight / 2,
      }

      smoothPanZoom(pan, zoom)
    }

    if (!this.printMode) {
      const clearPreview = (element: cytoscape.SingularElementArgument) => {
        const key = element.isNode() ? 'entity' : 'relation'
        const item: Entity | Relation = element.data(key)
        item.previewData = null
        item.previewStyle = null
        item.builtPreviewStyle = null
        element.data(key, item)
      }

      this.destroyCallbacks.push(
        this.diagram.eventBus.on('graph.layout', ({ layout, applyToLastChange }) => {
          this.layout(layout, false)?.then(() => {
            const moveEntities: EntityMove[] = []

            graph.nodes().forEach(node => {
              const { x, y } = node.position()
              moveEntities.push({ id: node.id(), x, y })
            })

            const change = { layout: layout.id, moveEntities }

            if (applyToLastChange) {
              this.diagram.activeDiagram.data.applyLayoutToLastChange(change)
            } else {
              this.diagram.activeDiagram.data.commitChange(change)
            }
          })
        }),

        this.diagram.eventBus.on('graph.fit', () => this.fit()),

        this.diagram.eventBus.on([ 'dataUpdated', 'activeFieldsChanged' ], () => {
          this.updateElements()
        }),

        this.diagram.eventBus.on('activeFiltersChanged', () => {
          this.runFilters()
        }),

        this.diagram.eventBus.on('editor.open', e => {
          if (this._editorTarget) clearPreview(this._editorTarget)

          let element: cytoscape.SingularElementArgument

          if (e.target.isEntity) {
            const node = graph.$id(e.target.id)
            if (!node.isNode()) return
            element = node
          } else {
            const edge = graph.$id(e.target.id)
            if (!edge.isEdge()) return
            element = edge
          }

          this._editorTarget = element
          // this.focusPanZoom.stateBefore ??= {
          //   pan: { ...graph.pan() },
          //   zoom: graph.zoom(),
          // }

          requestAnimationFrame(() => smoothPanZoomToElement(element))
        }),

        this.diagram.eventBus.on('editor.previewUpdated', () => {
          if (!this._editorTarget) return

          const key = this._editorTarget.isNode() ? 'entity' : 'relation'
          this._editorTarget.data(key, this._editorTarget.data(key))
        }),

        this.diagram.eventBus.on('editor.close', () => {
          if (this._editorTarget) clearPreview(this._editorTarget)

          this._editorTarget = null

          // if (!this.focusPanZoom.stateBefore) return

          // const { pan, zoom } = this.focusPanZoom.stateBefore
          // this.focusPanZoom.stateBefore = null

          // smoothPanZoom(pan, zoom)
        }),
      )

      this.$watch(() => this.diagram.activeDiagram, () => {
        this.clearElements()
        const updateElementsPromise = this.updateElements()

        // Apply diagram.initialZoomLevel if set
        const { initialZoomLevel } = this.diagram
        if (initialZoomLevel !== null) {
          updateElementsPromise.then(() => {
            graph.zoom(initialZoomLevel)

            const bbox = graph.elements().renderedBoundingBox({})

            const width = graph.width()
            const height = graph.height()

            const x = {
              left: -(bbox.x1 - this.fitPadding),
              center: -((bbox.x1 + bbox.x2) / 2 - width / 2),
              right: -(bbox.x2 + this.fitPadding - width),
            }

            const y = {
              top: -(bbox.y1 - this.fitPadding),
              center: -((bbox.y1 + bbox.y2) / 2 - height / 2),
              bottom: -(bbox.y2 + this.fitPadding - height),
            }

            graph.panBy({
              x: x[this.diagram.initialPan?.x ?? 'center'],
              y: y[this.diagram.initialPan?.y ?? 'center'],
            })
          })
        } else {
          updateElementsPromise.then(() => this.fit())
        }
      }, { immediate: true })
    } else {
      const updateElementsPromise = this.updateElements()
      updateElementsPromise.then(() => {
        spreadTaxiEdges(graph)
        this.fit()
        requestAnimationFrame(() => this.$emit('readyToPrint', graph))
      })
    }
  }

  beforeDestroy () {
    for (const cb of this.destroyCallbacks) cb()

    this.graphReady = false
    this._graph?.destroy()
    this._graph = undefined
  }

  // When clicking the graph container, cytoscape removes focus, so body ends up focused.
  // This focuses the graph container instead.
  redirectCytoscapeBlur (event: Event) {
    if (this.printMode || event.defaultPrevented) return

    setTimeout(() => {
      if (document.activeElement == null || document.activeElement == document.body) {
        (this.$el as HTMLElement).focus()
      }
    })
  }

  // Custom keyboard shortcuts
  onKeyDown (event: KeyboardEvent) {
    if (this.printMode || event.defaultPrevented) return

    type ModKey = 'ctrl/meta' | 'alt' | 'shift'

    const pressedModKeys = new Set<ModKey>()
    if (event.ctrlKey ? !event.metaKey : event.metaKey) pressedModKeys.add('ctrl/meta')
    if (event.altKey) pressedModKeys.add('alt')
    if (event.shiftKey) pressedModKeys.add('shift')

    const key = event.key.toLowerCase()
    const pressedKey = key

    const matchModKeys = (modKeys: ModKey[]) => {
      const set = new Set(modKeys)
      if (set.size !== pressedModKeys.size) return false
      for (const key of set) {
        if (!pressedModKeys.has(key)) return false
      }
      return true
    }

    const matchKey = (key: string) => pressedKey === key

    const actions: [ModKey[], [string, () => void][]][] = [
      [['ctrl/meta'], [
        ['a', () => this._graph?.elements().select()],
        ['d', () => this._graph?.elements().unselect()],
        ['z', () => this.diagram.activeDiagram.data.undo()],
        ['y', () => this.diagram.activeDiagram.data.redo()],
      ]],
      [['ctrl/meta', 'shift'], [
        ['z', () => this.diagram.activeDiagram.data.redo()],
      ]],
      [[], [
        ['delete', () => this.removeSelectedElements()],
        ['backspace', () => this.removeSelectedElements()],
      ]],
    ]

    for (const [ modKeys, modKeyActions ] of actions) {
      if (!matchModKeys(modKeys)) continue

      for (const [ key, handler ] of modKeyActions) {
        if (!matchKey(key)) continue

        event.preventDefault()
        handler()
      }
    }
  }

  onResize (rect: DOMRect) {
    this.rect.top = rect.top
    this.rect.left = rect.left
    this.rect.right = rect.right
    this.rect.bottom = rect.bottom
    this.rect.width = rect.width
    this.rect.height = rect.height

    if (this._graph) {
      if (rect.width === this._graph.width() && rect.height === this._graph.height()) return
      this._graph.resize()
    }
  }

  initialize () {
    // Initialize cytoscape
    const graph = this._graph = cytoscape({
      container: this.graphContainerEl,
      style: generateStyle(this),
      wheelSensitivity: 0.15,
      userZoomingEnabled: this.zoom,
      minZoom: 0,
      maxZoom: !this.printMode ? 1 : undefined,
      pixelRatio: !this.printMode ? 2 : 1,
    })

    graph.on('viewport', () => {
      const { x, y } = graph.pan()
      const zoom = graph.zoom()

      this.graphNodesEl.style.transform = [
        `translateX(${x}px)`,
        `translateY(${y}px)`,
        `scale(${zoom})`,
        'translate(100vw, 100vh)',
      ].join(' ')
    })

    const isElement = (target: cytoscape.Core | cytoscape.SingularElementArgument): target is cytoscape.SingularElementArgument => {
      return 'isNode' in target && 'isEdge' in target && (target.isNode() || target.isEdge())
    }

    if (!this.printMode) {
      // Initialize panzoom
      graph.panzoom({
        zoomOnly: true,
        fitSelector: '[!hiddenByFilter]',
        fitPadding: this.fitPadding,
        zoomInIcon: 'material-icons-outlined',
        zoomOutIcon: 'material-icons-outlined',
        resetIcon: 'material-icons-outlined',
        zoomFactor: 0.1,
      })

      let ignoreTap = false

      // Track node position changes
      if (this.diagram.enableDragAndDrop) {
        let grabbing = false
        let startPos: cytoscape.Position = { x: 0, y: 0 }
        let lastPos: cytoscape.Position = { x: 0, y: 0 }
        let delta: cytoscape.Position = { x: 0, y: 0 }
        let dragged = false
        const dragNodes = new Map<cytoscape.NodeSingular, { startPos: cytoscape.Position }>()
        const affectedTaxiEdges = new Set<cytoscape.EdgeSingular>()

        graph.on('grab', 'node', event => {
          if (!grabbing) {
            grabbing = true
            startPos = event.position
            delta = { x: 0, y: 0 }
            lastPos = { ...startPos }
            dragged = false
          }

          const node: cytoscape.NodeSingular = event.target
          if (node.locked()) return

          node.lock()
          dragNodes.set(node, { startPos: this.snapPos(node.position()) })
        })

        graph.on('tapdrag', event => {
          if (!grabbing) return

          const pos = event.position
          delta.x += pos.x - lastPos.x
          delta.y += pos.y - lastPos.y

          if (!delta.x && !delta.y) return

          if (!dragged) {
            dragged = true

            graph.batch(() => {
              for (const node of dragNodes.keys()) {
                const pos = this.snapPos(node.position())
                node.unlock()
                node.position(pos)
                node.lock()
              }
            })
          }

          const deltaSnapped = this.snapPos(delta)

          delta.x -= deltaSnapped.x
          delta.y -= deltaSnapped.y

          graph.batch(() => {
            let movedNodes = graph.collection()

            for (const node of dragNodes.keys()) {
              const pos = node.position()
              const newPos = { x: pos.x + deltaSnapped.x, y: pos.y + deltaSnapped.y }

              movedNodes = movedNodes.union(node)

              node.unlock()
              node.position(newPos)
              node.lock()
            }

            const affectedEdges = movedNodes.edgesWith(movedNodes)

            affectedEdges.forEach(edge => {
              const customTaxi: CustomTaxi | null = edge.data('customTaxi')
              if (!customTaxi || customTaxi.segmentPoints.length < 2) return

              affectedTaxiEdges.add(edge)

              const newCustomTaxi = cloneDeep(customTaxi)

              for (const [ point, side ] of [
                [ newCustomTaxi.segmentPoints[0], newCustomTaxi.from.side ],
                [ newCustomTaxi.segmentPoints[newCustomTaxi.segmentPoints.length - 1], newCustomTaxi.to.side ],
              ] as const) {
                const axis = (side === 'left' || side === 'right') ? 'x' : 'y'
                point[axis] += deltaSnapped[axis]
              }

              for (const point of newCustomTaxi.segmentPoints.slice(1, -1)) {
                point.x += deltaSnapped.x
                point.y += deltaSnapped.y
              }

              edge.data('customTaxi', newCustomTaxi)
            })
          })

          lastPos = pos
        })

        graph.on('tapend', () => {
          if (!grabbing) return

          grabbing = false

          for (const node of dragNodes.keys()) node.unlock()

          if (dragged) {
            const affectedTaxiEdges = graph.collection([ ...dragNodes.keys() ]).connectedEdges(':simple[?customTaxi]')

            const movedNodes = [ ...dragNodes ].filter(([ node, { startPos } ]) => {
              const pos = node.position()
              return pos.x !== startPos.x || pos.y !== startPos.y
            }).map(([ node ]) => node)

            if (movedNodes.length) {
              this.diagram.activeDiagram.data.commitChange({
                moveEntities: [ ...dragNodes.keys() ].map(node => {
                  const position = node.position()
                  return {
                    id: node.id(),
                    x: position.x,
                    y: position.y,
                  }
                }),
                edit: affectedTaxiEdges.length ? {
                  relations: affectedTaxiEdges.map(edge => ({
                    id: edge.id(),
                    customTaxi: cloneDeep(edge.data('customTaxi')),
                  })),
                } : undefined,
              })

              ignoreTap = true
              graph.autounselectify(true)

              requestAnimationFrame(() => {
                ignoreTap = false
                graph.autounselectify(false)
              })
            }
          }

          dragNodes.clear()
          affectedTaxiEdges.clear()
        })
      }

      // Fit on resize
      if (this.diagram.fitOnResize) graph.on('resize', () => this.fit())

      graph.on('vmousemove', event => this.elementHovered = isElement(event.target))

      graph.on('tap', event => {
        if (
          ignoreTap
          || !isElement(event.target)
          || this.contextMenu.show
          || event.originalEvent.ctrlKey
          || event.originalEvent.shiftKey
          || event.originalEvent.altKey
          || event.originalEvent.metaKey
        ) return

        const target: Entity | Relation = event.target.data(event.target.isNode() ? 'entity' : 'relation')

        if (this.editor?.object) {
          if (this.editor.object === target) return

          if (this.editor.hasChanges) {
            this.editor.showConfirmCloseDialog = true
            return
          }
        }

        if (this.diagram.enableEditing) {
          this.diagram.eventBus.emit({
            name: 'editor.open',
            target,
          })
        } else if (target.isEntity && target.type.showDetailsButton) {
          const showDetailsButton = typeof target.type.showDetailsButton === 'function'
            ? target.type.showDetailsButton(createContextItem(target))
            : target.type.showDetailsButton
          showDetailsButton?.onClick()
        }
      })

      graph.on('cxttap taphold', event => {
        // Taphold event should only open context menu on touch devices
        if (event.type === 'taphold') {
          if (event.originalEvent instanceof TouchEvent) {
            // Dispatch a touchend event to stop cytoscape touch panning
            window.dispatchEvent(new TouchEvent('touchend'))
          } else {
            // Ignore the event since it was triggered by a mouse
            return
          }
        }

        event.preventDefault()
        event.stopPropagation()

        if (event.target && event.target !== graph) {
          if (!event.target.selected()) {
            graph.elements().unselect()
            event.target.select()
          }
        } else {
          graph.elements().unselect()
        }

        const selectedItems = graph.elements(':selected').map(element => element.data(element.isNode() ? 'entity' : 'relation'))

        this.contextMenu = {
          show: true,
          position: event.renderedPosition,
          modelPosition: event.position,
          selectedItems,
        }
      })

      // graph.on('viewport', () => {
      //   if (this.animating || !this.focusPanZoom.stateBefore) return
      //   this.focusPanZoom.stateBefore = null
      // })

      let handlingSelection = false

      const handleSelection = () => {
        if (handlingSelection) return

        handlingSelection = true

        requestAnimationFrame(() => {
          handlingSelection = false

          const selection = graph.elements(':selected')

          if (this._editorTarget && (selection.length !== 1 || !selection.has(this._editorTarget))) {
            this.diagram.eventBus.emit({ name: 'editor.close' })
          }
        })
      }

      graph.on('select', event => {
        if (!isElement(event.target)) return

        const target = event.target.data(event.target.isNode() ? 'entity' : 'relation')

        if (this.editor?.object && this.editor.hasChanges && this.editor.object !== target) {
          event.target.unselect()
          this.editor.showConfirmCloseDialog = true
          return
        }

        event.target.data('selected', true)
        handleSelection()
      })

      graph.on('unselect', event => {
        if (!isElement(event.target)) return

        const target = event.target.data(event.target.isNode() ? 'entity' : 'relation')

        if (this.editor?.object && this.editor.hasChanges && this.editor.object === target) {
          event.target.select()
          return
        }

        event.target.data('selected', false)
        handleSelection()
      })

      // Spread taxi edges
      if (this.diagram.spreadTaxiEdges) {
        let handle = 0

        const start = async () => {
          const thisHandle = ++handle

          graph.batch(() => {
            graph.edges().forEach(edge => {
              if (edge.data('customPath')) edge.data('customPath', null)
            })
          })

          // await new Promise(resolve => requestAnimationFrame(resolve))
          await new Promise(resolve => setTimeout(resolve, 100))

          if (handle !== thisHandle) return

          handle = 0
          spreadTaxiEdges(graph)
        }

        this.destroyCallbacks.push(this.diagram.eventBus.on('graph.spreadTaxiEdges', () => {
          start()
        }))

        graph.on('add remove', 'node', () => {
          start()
        })

        graph.on('position lx:node-resize', 'node', e => {
          const node: cytoscape.NodeSingular = e.target
          const data = node.data()
          const entity: Entity = data.entity

          switch (e.type as string) {
            case 'position': {
              const pos = { ...node.position() }
              pos.x = safePrecision(pos.x)
              pos.y = safePrecision(pos.y)

              const oldPos = entity.position && { ...entity.position }
              if (oldPos) {
                oldPos.x = safePrecision(oldPos.x)
                oldPos.y = safePrecision(oldPos.y)
              }

              if (pos.x === oldPos?.x && pos.y === oldPos?.y) return

              start()
              break
            }

            case 'lx:node-resize': {
              start()
              break
            }
          }
        })

        graph.on('add remove', 'edge', () => {
          start()
        })

        graph.on('layoutstop', () => {
          start()
        })

        requestAnimationFrame(() => {
          start()
        })
      }
    }

    this.graphReady = true
  }

  clearElements () {
    const graph = this._graph
    if (!graph) return

    graph.elements().remove()
    this.addedItems.clear()
    this.entities = []
    this.relations = []
  }

  updateElements () {
    const promise = new Promise<void>(resolve => {
      const graph = this._graph
      if (!graph) return resolve()

      this.entities = this.diagram.activeDiagram.data.entities.slice()
      this.relations = this.diagram.activeDiagram.data.relations.slice()

      graph.batch(() => {
        const shouldLayout = !this.printMode && !graph.elements().length

        const items = new Map<string, Entity | Relation>([
          ...this.diagram.activeDiagram.data.entitiesMap,
          ...this.diagram.activeDiagram.data.relationsMap,
        ])

        const toAdd: (Entity | Relation)[] = []
        const toUpdate: (Entity | Relation)[] = []
        const toRemove: (Entity | Relation)[] = []

        for (const [id, item] of items) {
          if (!this.addedItems.has(id)) toAdd.push(item)
          else toUpdate.push(item)
        }

        for (const [id, item] of this.addedItems) {
          if (!items.has(id)) toRemove.push(item)
        }

        const selectAddedElements = !!(!this.printMode && graph.elements().length && toAdd.length)

        let toAddPos: cytoscape.Position | undefined = undefined
        if (!this.printMode && graph.elements().length && toAdd.some(item => item.isEntity && !item.position)) {
          const { x1, w, y2 } = graph.elements('[!hiddenByFilter]').boundingBox({})
          toAddPos = {
            x: x1 + w / 2,
            y: y2 + 128,
          }
        }

        const addedElements = graph.add(toAdd.map(item => (
          item.isEntity
            ? {
              group: 'nodes',
              classes: (
                'entity' +
                (item.position ? '' : ' needs-position')
              ),
              grabbable: !this.printMode && this.diagram.enableDragAndDrop,
              position: { ...(item.position ?? toAddPos ?? { x: 0, y: 0 }) },
              data: {
                id: item.id,
                entity: item,
                width: 160,
                height: 36,
              },
            }
            : {
              group: 'edges',
              classes: 'relation',
              data: {
                id: item.id,
                relation: item,
                source: item.from,
                target: item.to,
                customTaxi: item.customTaxi,
              },
            }
        )))

        if (selectAddedElements) {
          graph.elements().unselect()
          addedElements.select()
        }

        for (const item of toUpdate) {
          const element = graph.$id(item.id)

          const itemKey = item.isEntity ? 'entity' : 'relation'
          if (element.data(itemKey) !== item) element.data(itemKey, item)

          if (item.isEntity) {
            element.toggleClass('needs-position', !item.position)

            if (item.position) {
              const { x: oldX, y: oldY } = element.position()
              const { x, y } = item.position
              if (x !== oldX || y !== oldY) element.position({ x, y })
            }
          } else {
            const oldCustomTaxi = element.data('customTaxi')
            const newCustomTaxi = item.customTaxi

            if (newCustomTaxi !== oldCustomTaxi) {
              element.data('customTaxi', item.customTaxi)
            }
          }
        }

        for (const item of toRemove) {
          graph.$id(item.id).remove()
        }

        this.diagram.eventBus.emit({ name: 'graph.spreadTaxiEdges' })

        const elements = graph.elements()
        const mainEntityNode = elements.$id(this.diagram.mainEntityId)

        this.addedItems = items

        // Calculate hierarchy
        if (!this.printMode) {
          const getEntity = (id: string) => {
            const item = items.get(id)
            return item instanceof Entity ? item : null
          }

          for (const item of items.values()) {
            item.isParent = false
            item.isChild = false

            if (item.isEntity) {
              item.connectedRelations = []
              item.incomingRelations = []
              item.outgoingRelations = []
            } else {
              item.fromEntity = null
              item.toEntity = null
            }
          }

          elements.edges().forEach(edge => {
            const relation: Relation = edge.data('relation')

            relation.fromEntity = getEntity(relation.from)
            relation.toEntity = getEntity(relation.to)

            if (relation.fromEntity) {
              relation.connectedEntities.push(relation.fromEntity)
              relation.fromEntity.connectedRelations.push(relation)
              relation.fromEntity.outgoingRelations.push(relation)
            }

            if (relation.toEntity) {
              relation.connectedEntities.push(relation.toEntity)
              relation.toEntity.connectedRelations.push(relation)
              relation.toEntity.incomingRelations.push(relation)
            }
          })

          mainEntityNode.predecessors().not(mainEntityNode).forEach(element => {
            const item: Entity | Relation = element.data(element.isNode() ? 'entity' : 'relation')
            item.isParent = true
          })

          mainEntityNode.successors().not(mainEntityNode).forEach(element => {
            const item: Entity | Relation = element.data(element.isNode() ? 'entity' : 'relation')
            item.isChild = true
          })
        }

        // Build styles
        if (!this.printMode) {
          for (const item of items.values()) {
            item.buildAndApplyStyles()
          }
        }

        // Run filters
        this.runFilters()

        const onDone = () => {
          graph.one('render', () => requestAnimationFrame(() => resolve()))

          graph.batch(() => {
            if (!this.printMode) {
              // Set initial entity positions
              graph.nodes().forEach(node => {
                const entity: Entity = node.data('entity')
                if (!entity.position) {
                  entity.initialState.position = { ...node.position() }
                  entity.position = { ...node.position() }
                  node.removeClass('needs-position')
                }
              })
            }

            // Fit graph to screen, if necessary
            if (shouldLayout || toAddPos) this.fit()
          })
        }

        const nodesToLayout = shouldLayout ? graph.nodes('.needs-position') : null

        if (nodesToLayout?.length) {
          this.$nextTick(() => {
            const nodesToLock = graph.nodes().not(nodesToLayout).not(':locked')
            nodesToLock.lock()

            this.layout(this.diagram.activeDiagram.settings.activeLayout, false)?.then(() => graph.batch(() => {
              nodesToLock.unlock()
              onDone()
            }))
          })
        } else {
          onDone()
        }
      })
    })

    promise.then(() => {
      this.diagram.eventBus.emit({ name: 'graph.updatedElements' })
    })

    return promise
  }

  runFilters () {
    const graph = this._graph
    if (!graph) return

    const filters = this.diagram.filters.filter(filter => filter.filterWhen === 'active' ? filter.active : !filter.active)

    graph.batch(() => {
      const elements = graph.elements()
      if (!elements.length) return

      elements.data('hiddenByFilter', false)

      elements.forEach(element => {
        // Skip elements that are already hidden
        if (element.data('hiddenByFilter')) return

        const context = createContextItem(element.data(element.isNode() ? 'entity' : 'relation'))

        // Hide if at least one filter returns false
        if (filters.some(filter => !filter.filter(context))) {
          element.data('hiddenByFilter', true)

          // If the element is a node, hide connected edges
          if (element.isNode()) {
            const connectedEdges = element.connectedEdges() as cytoscape.CollectionReturnValue
            connectedEdges.data('hiddenByFilter', true)
          }
        }
      })

      if (this.diagram.hideDanglingEntitiesAfterFilter) {
        const mainEntityNode = elements.$id(this.diagram.mainEntityId)
        if (!mainEntityNode) return

        // Get the component of the main entity
        const mainComponent = elements.componentsOf(mainEntityNode)[0]

        // Get the components of the main component after filters
        const components = mainComponent.filter('[!hiddenByFilter]').components()

        // Loop through the components and hide them, except for the one with the main entity
        for (const elements of components) {
          if (elements.has(mainEntityNode)) continue

          elements.forEach(element => {
            element.data('hiddenByFilter', true)
          })
        }
      }
    })
  }

  snapPos (pos: cytoscape.Position) {
    const size = this.diagram.dragAndDropGridSize
    const snapNumber = (n: number) => size
      ? Math.round(n / size) * size
      : n
    return { x: snapNumber(pos.x), y: snapNumber(pos.y) }
  }

  layout (layout?: LayoutDefinition | null, animate = layout?.animate ?? false) {
    const graph = this._graph
    if (!graph) return

    return new Promise<void>(resolve => {
      const elements = graph.elements('[!hiddenByFilter]')

      let baseOptions = {
        fit: false,
        spacingFactor: layout?.spacingFactor ?? 1.3,
        animate: animate,
        animationDuration: animate ? layout?.animationDuration ?? 1000 : undefined,
        animationEasing: animate ? layout?.animationEasing ?? 'ease-out' as any : undefined,
        transform: layout?.inverted ? (_: cytoscape.NodeSingular, { x, y }: cytoscape.Position) => ({ x: -x, y: -y }) : undefined,
        stop: () => {
          if (this.diagram.dragAndDropGridSize) {
            elements.forEach(el => {
              el.position(this.snapPos(el.position()))
            })
          }

          resolve()
        },
      }

      let options: cytoscape.LayoutOptions | dagre.DagreLayoutOptions

      switch (layout?.type) {
        case 'dagre': {
          options = {
            ...baseOptions,
            name: 'dagre',
            nodeSep: layout.nodeSep,
            edgeSep: layout.edgeSep,
            rankSep: layout.rankSep,
            rankDir: layout.rankDir,
            align: layout.align,
            ranker: layout.ranker,
          }
          break
        }

        default: {
          options = {
            ...baseOptions,
            name: 'breadthfirst',
            directed: layout?.directed ?? false,
            grid: layout?.grid ?? false,
            maximal: layout?.maximal ?? false,
            avoidOverlap: true,
          }
          break
        }
      }

      elements.layout(options).run()
    })
  }

  fit () {
    const graph = this._graph
    if (!graph) return

    graph.fit(graph.elements('[!hiddenByFilter]'), this.fitPadding)
  }

  removeSelectedElements () {
    if (!this._graph) return

    const entityIds = new Set<string>()
    const relationIds = new Set<string>()

    this._graph.elements(':selected').forEach(element => {
      const target: Entity | Relation = element.data(element.isNode() ? 'entity' : 'relation')
      if (target.isEntity) {
        if (target.isMainEntity) return
        entityIds.add(target.id)
      } else {
        relationIds.add(target.id)
      }
    })

    if (!entityIds.size && !relationIds.size) return

    this.diagram.activeDiagram.data.remove({
      entities: [ ...entityIds ],
      relations: [ ...relationIds ],
    })
  }
}
</script>

<style lang="scss">
.lassox-diagram__Graph {
  position: relative;
  width: 1px;
  flex-grow: 1;
  overscroll-behavior: none;
  touch-action: none;

  &:focus {
    outline: none;
  }

  &-scaler {
    position: absolute;
    top: 0;
    left: 0;
    transform-origin: top left;
  }

  &-container {
    position: relative;
    z-index: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
  }

  &--has-hovered-element &-container {
    cursor: pointer;
  }

  &-nodes {
    position: absolute;
    z-index: 11;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    transform-origin: top left;
  }

  .cy-panzoom {
    display: flex;
    flex-direction: column;
    top: 16px;
    left: 16px;
    padding: 0;
  }

  .cy-panzoom-zoom-button {
    position: relative;
    top: auto;
    left: auto;
    display: flex;
    justify-content: center;
    align-items: center;
    width: 24px;
    height: 24px;
    padding: 0;
    border: none;
    margin: 0;
    border-radius: 2px;
    overflow: hidden;
    background-color: white;
    box-shadow: 0 2px 5px 0 rgba(black, 0.1);

    & + .cy-panzoom-zoom-button {
      margin-top: 8px;
    }

    .icon {
      font-size: 18px;

      &::after {
        position: relative;
      }
    }

    &::after {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      content: '';
      background-color: rgba(black, 0.16);
      opacity: 0;
      transition: opacity 100ms;
    }

    &:hover::after {
      opacity: 0.25;
    }

    &:focus::after {
      opacity: 0.5;
    }

    &:active::after {
      opacity: 1;
    }
  }

  .cy-panzoom-zoom-in .icon::after {
    content: 'add';
  }

  .cy-panzoom-zoom-out .icon::after {
    content: 'remove';
  }

  .cy-panzoom-reset .icon::after {
    content: 'open_in_full';
  }

  &_entity {
    position: relative;
    box-sizing: border-box;
    min-width: 160px;
    max-width: 480px;
    min-height: 32px;
    border: 2px solid rgba(black, 0.12);
    background-color: white;
    border-radius: 2px;
    user-select: none;
    pointer-events: none;
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;

    &-selected-outline {
      position: absolute;
