<template>
  <transition
    appear
    :duration="{ enter: 150, leave: 75 }"
  >
    <div
      :class="[
        'lassox-diagram__Dialog',
        loading && 'lassox-diagram__Dialog--loading',
        scrollable && !loading && 'lassox-diagram__Dialog--scrollable',
        canScrollUp && 'lassox-diagram__Dialog--can-scroll-up',
        canScrollDown && 'lassox-diagram__Dialog--can-scroll-down',
      ]"
    >
      <div
        class="lassox-diagram__Dialog-backdrop"
        @click="() => dismissable && close()"
      />

      <div
        class="lassox-diagram__Dialog-box"
        tabindex="-1"
        :style="{ maxWidth: `${maxWidth}px` }"
      >
        <div
          v-if="title || dismissable || $slots['header'] || $slots['title']"
          class="lassox-diagram__Dialog-header"
        >
          <slot
            name="header"
            v-bind="slotProps"
          >
            <div
              v-if="title"
              class="lassox-diagram__Dialog-title"
            >
              <slot
                name="title"
                v-bind="slotProps"
              >
                <div
                  v-if="title"
                  v-text="title"
                />
              </slot>
            </div>

            <IconButton
              v-if="dismissable"
              class="lassox-diagram__Dialog-close-button"
              icon="close"
              size="normal"
              @click="close"
            />
          </slot>
        </div>

        <div
          v-if="content || $slots['content'] || loading"
          class="lassox-diagram__Dialog-content"
        >
          <CustomScroll
            ref="customScroll"
            class="lassox-diagram__Dialog-content-scroll"
            :paddingTop="(title || dismissable || $slots['header'] || $slots['title']) ? 24 : 0"
            :paddingBottom="($slots['actions']) ? 24 : 0"
          >
            <div class="lassox-diagram__Dialog-content-inner">
              <slot
                name="content"
                v-bind="slotProps"
              >
                <div
                  v-if="content"
                  v-text="content"
                />
              </slot>
            </div>
          </CustomScroll>

          <div class="lassox-diagram__Dialog-content-scroll-shadow-top" />

          <div class="lassox-diagram__Dialog-content-scroll-shadow-bottom" />

          <div
            class="lassox-diagram__Dialog-content-loading-overlay"
            :style="{
              opacity: loading ? '1' : '0',
              pointerEvents: loading ? '' : 'none',
            }"
          >
            <LoadingSpinner style="margin: auto" />
          </div>
        </div>

        <div
          v-if="$slots['actions']"
          class="lassox-diagram__Dialog-actions"
        >
          <slot
            name="actions"
            v-bind="slotProps"
          />
        </div>
      </div>
    </div>
  </transition>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import IconButton from './IconButton.vue'
import LoadingSpinner from './LoadingSpinner.vue'
import CustomScroll from './CustomScroll.vue'

const sizes = {
  '1x': 320,
  '2x': 360,
  '3x': 400,
  '4x': 440,
  '5x': 480,
}

@Component({
  components: {
    IconButton,
    LoadingSpinner,
    CustomScroll,
  },
})

export default class Dialog extends Vue {
  @Prop(Boolean)
  readonly dismissable?: boolean

  @Prop(String)
  readonly title?: string

  @Prop(String)
  readonly content?: string

  @Prop({ type: [ String, Number ], default: '1x' })
  readonly size!: string | number

  @Prop({ type: Boolean, default: false })
  readonly loading!: boolean

  @Prop(Function)
  readonly onClose?: () => void

  boxEl: HTMLElement | null = null
  customScroll: CustomScroll | null = null

  contentScrollHeight = 0
  contentScrollInnerHeight = 0
  contentScrollTop = 0

  get scrollable () {
    return this.contentScrollInnerHeight > this.contentScrollHeight
  }

  get canScrollUp () {
    return this.customScroll?.canScrollUp ?? false
  }

  get canScrollDown () {
    return this.customScroll?.canScrollDown ?? false
  }

  get maxWidth () {
    if (typeof this.size === 'number') return this.size
    if (this.size in sizes) return sizes[this.size as keyof typeof sizes]
    return sizes['1x']
  }

  get slotProps () {
    return {
      close: this.close,
    }
  }

  mounted () {
    this.updateRefs()

    this.boxEl?.focus()
  }

  updated () {
    this.updateRefs()
  }

  beforeDestroy () {
    this.customScroll = null
  }

  updateRefs () {
    this.boxEl = this.$el.querySelector<HTMLElement>('.lassox-diagram__Dialog-box')
    this.customScroll = this.$refs.customScroll as any ?? null
  }

  close () {
    this.$emit('close')
    this.onClose?.()
  }
}
</script>

<style lang="scss">
.lassox-diagram__Dialog {
  position: absolute;
  z-index: 0;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 32px;
  pointer-events: none;

  &-backdrop {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(black, 0.32);
    pointer-events: auto;
  }

  &-box {
    position: relative;
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 320px;
    border-radius: 4px;
    background-color: white;
    overflow: hidden;
    box-shadow: 0 2px 10px 0 rgba(black, 0.2);
    pointer-events: auto;

    &:focus {
      outline: none;
    }
  }

  &-header,
  &-actions {
    padding: 24px;
  }

  &-header,
  &-actions {
    position: relative;
    z-index: 1;
    // background-color: white;
  }

  &-header {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    flex-grow: 0;
  }

  &-title {
    flex-grow: 1;
    flex-shrink: 1;
    margin-right: auto;
    color: rgba(black, 0.87);
    font-size: 17px;
    line-height: 24px;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  &-title + &-close-button {
    margin-left: 32px;
  }

  &-content {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 0;
    flex-shrink: 1;
    flex-grow: 1;
    // overflow: hidden;

    &-loading-overlay {
      position: absolute;
      z-index: 1;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      display: flex;
      background-color: white;
      transition: opacity 100ms;
    }

    &-scroll {
      & > .lassox-diagram__CustomScroll-wrapper > .lassox-diagram__CustomScroll-content {
        position: relative;
      }

      &-shadow-top,
      &-shadow-bottom {
        position: absolute;
        z-index: 1;
        left: 0;
        right: 0;
        height: 4px;
        opacity: 0;
        pointer-events: none;
        overflow: hidden;
        transition: opacity 100ms;

        &::before {
          content: '';
          position: absolute;
          bottom: 100%;
          width: 100%;
          height: 100%;
          box-shadow: 0 0 4px 0 rgba(black, 0.2);
        }
      }

      &-shadow-top {
        top: 0;
      }

      &-shadow-bottom {
        bottom: 0;
        transform: rotate(180deg);
      }
    }

    &-inner {
      display: flex;
      flex-direction: column;
      min-height: 0;
      flex-shrink: 1;
      flex-grow: 1;
      padding: 0 24px;
    }

    &:first-child &-inner,
    &:first-child &-loading-overlay {
      padding-top: 24px;
    }

    &:last-child &-inner,
    &:last-child &-loading-overlay {
      padding-bottom: 24px;
    }
  }

  &--loading &-content {
    min-height: 48px + 24px * 2;

    &:first-child,
    &:last-child {
      min-height: 48px + 24px * 2 + 24px;
    }

    &:first-child:last-child {
      min-height: 48px + 24px * 2 + 24px * 2;
    }
  }

  &--can-scroll-up &-header {
    background-color: white;
  }

  &--can-scroll-up &-content-scroll-shadow-top {
    opacity: 1;
  }

  &--can-scroll-down &-actions {
    background-color: white;
  }

  &--can-scroll-down &-content-scroll-shadow-bottom {
    opacity: 1;
  }

  &-actions {
    flex-shrink: 0;
    flex-grow: 0;
  }
}

// Transition
.lassox-diagram__Dialog {
  &.v-enter-active {
    & > .lassox-diagram__Dialog-backdrop {
      transition: opacity 150ms linear;
      opacity: 0;
    }

    & > .lassox-diagram__Dialog-box {
      transition: opacity 45ms linear, transform 150ms ease-out;
      opacity: 0;
      transform: scale(0.8);
    }

    &.v-enter-to {
      & > .lassox-diagram__Dialog-backdrop {
        opacity: 1;
      }

      & > .lassox-diagram__Dialog-box {
        opacity: 1;
        transform: scale(1);
      }
    }
  }

  &.v-leave-active {
    transition: opacity 75ms linear;
    opacity: 1;

    &.v-leave-to {
      opacity: 0;
    }
  }
}
</style>
