<template>
  <div class="lassox-diagram__TooltipRoot">
    <Tooltip
      v-for="(tooltip, i) in tooltips"
      :key="i"
      v-bind="tooltip"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component } from 'vue-property-decorator'
import Tooltip from './Tooltip.vue'
import { getStore } from '../tooltips'

@Component({
  components: {
    Tooltip,
  },
})

export default class TooltipRoot extends Vue {
  get store () { return getStore(this.$root) }

  get tooltips () { return this.store.tooltips }
}
</script>

<style lang="scss">
.lassox-diagram__TooltipRoot {
  position: fixed;
  z-index: 1;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
}
</style>
