<template>
  <BaseButton
    :class="[
      'lassox-diagram__Button',
      `lassox-diagram__Button--type-${type}`,
      label && 'lassox-diagram__Button--has-label',
      (icon || leadingIcon) && 'lassox-diagram__Button--has-leading-icon',
      trailingIcon && 'lassox-diagram__Button--has-trailing-icon',
      (icon || leadingIcon) && !trailingIcon && !label && 'lassox-diagram__Button--has-icon-only',
    ]"
    v-bind="{ label, icon, leadingIcon, trailingIcon, disabled }"
    v-on="$listeners"
  >
    <slot />
  </BaseButton>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'

const types = new Set(['outlined', 'primary'])

@Component({
  components: {
    BaseButton,
  },
})

export default class Button extends Vue {
  @Prop({ type: String, validator: (type: string) => types.has(type), default: 'outlined' })
  readonly type!: string

  @Prop({ type: String })
  readonly label?: string

  @Prop({ type: String })
  readonly icon?: string

  @Prop({ type: String })
  readonly leadingIcon?: string

  @Prop({ type: String })
  readonly trailingIcon?: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean
}
</script>

<style lang="scss">
.lassox-diagram__Button {
  min-width: 64px;
  height: 32px;
  padding: 0 16px;
  border-radius: 2px;

  &--has-icon-only {
    width: 32px;
    min-width: 0;
    padding: 0;
  }

  &--has-label {
    .lassox-diagram__BaseButton_leading-icon {
      margin-left: -4px;
    }

    .lassox-diagram__BaseButton_trailing-icon {
      margin-right: -4px;
    }
  }

  &--type-outlined .lassox-diagram__BaseButton_outline {
    color: rgba(black, 0.12);
  }

  &--type {
    &-outlined .lassox-diagram__BaseButton_outline {
      color: rgba(black, 0.12);
    }

    &-primary {
      color: white;
      background-color: #ffa07a;
    }
  }
}
</style>
