import Vue from 'vue'
import ReactiveDictionary from './reactive-dictionary'

export default class ReactiveMap<K, V> {
  constructor (iterable?: Iterable<[K, V]>) {
    if (iterable) {
      for (const [ key, value ] of iterable) {
        this.set(key, value)
      }
    }

    Vue.observable(this)
  }

  private _dictionary = new ReactiveDictionary<K, {
    index: number
    value: V
  }>()

  private _entries: [K, V][] = Vue.observable([])

  get size () {
    return this._entries.length
  }

  has (key: K) {
    return this._dictionary.has(key)
  }

  get (key: K) {
    return this._dictionary.get(key)?.value
  }

  set (key: K, value: V) {
    const dictItem = this._dictionary.get(key)
    if (dictItem) {
      dictItem.value = value
      return
    }

    const entry: [K, V] = [ key, value ]
    const index = this._entries.push(entry) - 1

    this._dictionary.set(key, {
      index,
      get value () { return entry[1] },
      set value (newValue) { Vue.set(entry, 1, newValue) },
    })
  }

  delete (key: K) {
    const dictItem = this._dictionary.get(key)
    if (!dictItem) return

    this._dictionary.delete(key)
    this._entries.splice(dictItem.index, 1)

    this._entries.forEach((entry, index) => {
      if (index < dictItem.index) return
      const dictItem2 = this._dictionary.get(entry[0])
      if (dictItem2) dictItem2.index--
    })
  }

  clear () {
    this._dictionary = new ReactiveDictionary()
    this._entries.splice(0)
  }

  entries (): [K, V][] {
    return this._entries.map(([ key, value ]) => [ key, value ])
  }

  keys () {
    return this._entries.map(([ key ]) => key)
  }

  values () {
    return this._entries.map(([ , value ]) => value)
  }

  forEach (callbackfn: (value: V, key: K, map: this) => void) {
    this._entries.forEach(([ key, value ]) => callbackfn(value, key, this))
  }

  *[Symbol.iterator] (): IterableIterator<[K, V]> {
    for (const [ key, value ] of this._entries) {
      yield [ key, value ]
    }
  }
}
