<template>
  <DropdownMenu
    v-bind="$attrs"
    v-on="$listeners"
  >
    <template v-for="(items, groupI) in actions">
      <DropdownMenuDivider
        v-if="groupI"
        :key="`group-${groupI}-divider`"
      />

      <DropdownMenuItem
        v-for="(item, itemI) in items"
        :key="`group-${groupI}-item-${itemI}`"
        :label="item.label"
        @click="item.onClick"
      />
    </template>
  </DropdownMenu>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import type DiagramVm from './Diagram.vue'
import type { default as Diagram, Entity, RelationType } from '../diagram'
import type { DiagramDataDefinition } from '../types/DiagramData'
import AddRelationDialog from './AddRelationDialog.vue'
import ConfirmAdditionDialog from './ConfirmAdditionDialog.vue'

interface Item {
  label: string
  onClick: () => void
}

const filterOutExistingData = (diagram: Diagram, data: DiagramDataDefinition): DiagramDataDefinition => {
  const activeData = diagram.activeDiagram.data
  return {
    entities: data.entities?.filter(e => !activeData.entitiesMap.has(e.id)),
    relations: data.relations?.filter(r => !activeData.relationsMap.has(r.id)),
  }
}

export const getActions = (diagramVm: DiagramVm, entity: Entity) => {
  const { diagram } = diagramVm

  const items = {
    new: [] as Item[],
    existing: [] as Item[],
  }

  const showAddRelationDialog = (relationType: RelationType, type: 'parent' | 'child') => diagram.store.showDialog(AddRelationDialog, {
    relationType,
    entity,
    asParent: type === 'parent',
  })

  const addExisting = async (relationType: RelationType, type: 'parents' | 'children') => {
    if (!diagram.methods.getEntityData) return

    const label = relationType.labels.pluralFrom || relationType.labels.plural

    const closeLoadingToast = diagram.store.showToast({
      content: `Henter eksisterende ${label.toLowerCase()}...`,
      dismissable: false,
      duration: 0,
      showLoadingSpinner: true,
    })

    const unfilteredData = await diagram.methods.getEntityData({
      ids: [ entity.id ],
      relationTypes: [ relationType.id ],
      parents: type === 'parents' ? 1 : 0,
      children: type === 'children' ? 1 : 0,
    }).catch(err => {
      console.error('getEntityData() failed', err)
      return null
    })

    if (!unfilteredData) {
      closeLoadingToast()
      diagram.store.showToast({ content: `Vi kunne ikke hente eksisterende ${label.toLowerCase()}.` })
      return
    }

    const data = filterOutExistingData(diagram, unfilteredData)

    closeLoadingToast()

    if (data.entities?.length || data.relations?.length) {
      diagram.store.showDialog(ConfirmAdditionDialog, { data })
    } else {
      if (unfilteredData.relations?.length || unfilteredData.entities?.find(e => e.id !== entity.id)) {
        diagram.store.showToast({ content: `Alle eksisterende ${label.toLowerCase()} er allerede tilføjet.` })
      } else {
        diagram.store.showToast({ content: `Ingen eksisterende ${label.toLowerCase()} blev fundet.` })
      }
    }
  }

  for (const {
    type,
    supportsParent,
    supportsAddExistingParents,
    supportsChild,
    supportsAddExistingChildren,
  } of entity.type.supportedRelations.values()) {
    if (supportsParent) {
      items.new.push({
        label: type.labels.newParent ?? 'Ny(t) ' + (type.labels.singularFrom || type.labels.singular).toLowerCase(),
        onClick: () => showAddRelationDialog(type, 'parent'),
      })

      if (supportsAddExistingParents) {
        items.existing.push({
          label: type.labels.existingParents ?? 'Eksisterende ' + (type.labels.pluralFrom || type.labels.plural).toLowerCase(),
          onClick: () => addExisting(type, 'parents'),
        })
      }
    }

    if (supportsChild) {
      items.new.push({
        label: type.labels.newChild ?? 'Ny(t) ' + (type.labels.singularTo || type.labels.singular).toLowerCase(),
        onClick: () => showAddRelationDialog(type, 'child'),
      })

      if (supportsAddExistingChildren) {
        items.existing.push({
          label: type.labels.existingChildren ?? 'Eksisterende ' + (type.labels.pluralTo || type.labels.plural).toLowerCase(),
          onClick: () => addExisting(type, 'children'),
        })
      }
    }
  }

  return [
    items.new,
    items.existing,
  ].filter(items => items.length)
}

@Component({
  components: {
    DropdownMenu,
    DropdownMenuItem,
    DropdownMenuDivider,
  },

  inheritAttrs: false,
})

export default class AddRelationDropdownMenu extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly diagramVm!: DiagramVm

  @Prop({ type: Object, required: true })
  readonly entity!: Entity

  get entityType () {
    return this.entity.type
  }

  get actions () {
    return getActions(this.diagramVm, this.entity)
  }
}
</script>
