<template>
  <Dialog
    class="lassox-diagram__AddRelationDialog"
    :dismissable="true"
    :title="`Tilføj ${relationTypeLabel.toLowerCase()}`"
    size="2x"
    :onClose="dismiss"
  >
    <template v-slot:content>
      <EntitySelector
        ref="entitySelector"
        :entityTypes="supportedEntityTypes"
        @change="model => entitySelectorModel = model"
      />

      <div style="margin-top: 16px" />

      <!-- <DropdownMenuDivider style="margin: 24px 0" /> -->

      <DataCreator
        ref="relationDataCreator"
        :type="relationType"
        v-model="relationData"
      />
    </template>

    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          @click="dismiss"
        />

        <Button
          label="Tilføj"
          type="primary"
          :disabled="!canConfirm"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Inject, Prop, Ref } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import DataCreator from './DataCreator.vue'
import FieldContainer from './FieldContainer.vue'
import DropdownField from './DropdownField.vue'
import TextField from './TextField.vue'
import EntitySelector, { EntitySelectorModel } from './EntitySelector.vue'
import EntitySearchBar from './EntitySearchBar.vue'
import EditorFieldGroups from './EditorFieldGroups.vue'
import EditorFieldGroup from './EditorFieldGroup.vue'
import EditorField from './EditorField.vue'
import TabBar from './TabBar.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import { ContextItem, createContextItem, Entity, EntityDefinition, EntityType, RelationDefinition, RelationType } from '../diagram'
import _cloneDeep from 'lodash.clonedeep'
import _merge from 'lodash.merge'

@Component({
  components: {
    Dialog,
    DataCreator,
    FieldContainer,
    DropdownField,
    TextField,
    EntitySelector,
    EntitySearchBar,
    EditorFieldGroups,
    EditorFieldGroup,
    EditorField,
    TabBar,
    DropdownMenuDivider,
    ButtonGroup,
    Button,
  },
})

export default class AddRelationDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Ref()
  readonly relationDataCreator?: DataCreator

  @Ref()
  readonly entitySelector?: EntitySelector

  @Prop({ type: Object, required: true })
  readonly relationType!: RelationType

  @Prop({ type: Object, required: true })
  readonly entity!: Entity

  @Prop({ type: Boolean, required: true })
  readonly asParent!: boolean

  @Prop(Function)
  readonly onConfirm?: () => void

  @Prop(Function)
  readonly onDismiss?: () => void

  isConfirming = false

  relationData: Record<string, any> = {}

  entitySelectorModel: EntitySelectorModel = null

  get diagram () {
    return this.diagramVm.diagram
  }

  get relationTypeLabel () {
    const { labels } = this.relationType
    return (
      (this.asParent ? labels.singularFrom : labels.singularTo)
      ?? labels.singular
    )
  }

  get supportedEntityTypes () {
    const types = new Set<EntityType>()

    for (const support of this.relationType.supports) {
      if (this.asParent) {
        if (support.to !== this.entity.type.id) continue
      } else {
        if (support.from !== this.entity.type.id) continue
      }

      const type = this.diagram.entityTypes.get(this.asParent ? support.from : support.to)
      types.add(type)
    }

    return [ ...types ]
  }

  get canConfirm () {
    if (this.isConfirming) return false
    if (!this.entitySelectorModel) return false
    return true
  }

  close () {
    this.$emit('close')
  }

  async confirm () {
    const { canConfirm, entitySelectorModel } = this

    if (!canConfirm || !entitySelectorModel) return

    this.isConfirming = true

    const generateId = (prefix: string, items: Map<string, any>) => {
      const time = Date.now()
      let i = 0
      let id = ''
      while (!id || items.has(id)) {
        id = `${prefix}-${time}-${i}`
        i++
      }
      return id
    }

    const createEntityDefinitionContextItem = (definition: EntityDefinition): ContextItem => ({
      isEntity: true,
      isRelation: false,
      type: definition.type,
      id: definition.id,
      data: definition.data || {},
      isParent: false,
      isChild: false,
      activeLayout: this.diagram.activeDiagram.settings.activeLayout,

      isMainEntity: false,
      connectedRelations: [],
      incomingRelations: [],
      outgoingRelations: [],

      fromEntity: null,
      toEntity: null,
      connectedEntities: [],
    })

    let newEntity: EntityDefinition | null = null

    const entity1Context = createContextItem(this.entity)
    let entity2Context: ContextItem

    if (entitySelectorModel.mode === 'search') {
      const suggestion = entitySelectorModel.selectedSuggestion
      const { id } = suggestion

      if (suggestion.entity) {
        entity2Context = createContextItem(suggestion.entity)
      } else if (suggestion.entityDefinition) {
        newEntity = _cloneDeep(suggestion.entityDefinition)

        if (this.diagram.methods.getEntityData) {
          // TODO : We could add actual handling here instead of ignoring the error.

          const data = await this.diagram.methods.getEntityData({
            ids: [ suggestion.id ],
            relationTypes: [],
            parents: 0,
            children: 0,
          }).catch(err => {
            console.error('getEntityData() failed', err)
            this.diagram.store.showToast({ content: `Vi kunne ikke hente data for "${suggestion.text}"` })
            return null
          })

          const responseEntity = data?.entities?.find(e => e.id === id)

          if (responseEntity) newEntity = _merge(newEntity, responseEntity)
        }

        entity2Context = createEntityDefinitionContextItem(newEntity)
      } else {
        throw Error('No entity or entityDefinition in entitySelectorModel.selectedSuggestion')
      }
    } else {
      newEntity = {
        type: entitySelectorModel.entityType.id,
        id: generateId('CUSTOM-ENTITY', this.diagram.activeDiagram.data.entitiesMap),
        data: entitySelectorModel.entityData,
      }

      entity2Context = createEntityDefinitionContextItem(newEntity)
    }

    const entityContexts = [ entity1Context, entity2Context ]
    if (this.asParent) entityContexts.reverse()
    const [ fromEntityContext, toEntityContext ] = entityContexts

    const newRelation: RelationDefinition = {
      type: this.relationType.id,
      id: generateId('CUSTOM-RELATION', this.diagram.activeDiagram.data.relationsMap),
      data: this.relationData,
      from: fromEntityContext.id,
      to: toEntityContext.id,
    }

    const relationContext: ContextItem = {
      isEntity: false,
      isRelation: true,
      type: newRelation.type,
      id: newRelation.id,
      data: newRelation.data || {},
      isParent: toEntityContext.isMainEntity || toEntityContext.isParent,
      isChild: fromEntityContext.isMainEntity || fromEntityContext.isChild,
      activeLayout: this.diagram.activeDiagram.settings.activeLayout,

      isMainEntity: false,
      connectedRelations: [],
      incomingRelations: [],
      outgoingRelations: [],

      fromEntity: fromEntityContext,
      toEntity: toEntityContext,
      connectedEntities: [ fromEntityContext, toEntityContext ],
    }

    if (relationContext.isParent) {
      fromEntityContext.isParent = true
    }

    fromEntityContext.connectedRelations.push(relationContext)
    fromEntityContext.outgoingRelations.push(relationContext)

    if (relationContext.isChild) {
      toEntityContext.isChild = true
    }

    toEntityContext.connectedRelations.push(relationContext)
    toEntityContext.incomingRelations.push(relationContext)

    if (!this.relationDataCreator) throw Error('this.relationDataCreator not found')

    const relationValid = this.relationDataCreator.validate(relationContext)
    let entityValid = true

    if (newEntity) {
      if (!this.entitySelector) throw Error('this.entitySelector not found')
      entityValid = this.entitySelector.validate(entity2Context)
    }

    if (!relationValid || !entityValid) {
      this.isConfirming = false
      return
    }

    this.diagram.activeDiagram.data.add({
      entities: newEntity ? [ newEntity ] : undefined,
      relations: [ newRelation ],
    })

    this.close()
    this.onConfirm?.()
  }

  dismiss () {
    this.close()
    this.onDismiss?.()
  }
}
</script>
