<template>
  <div
    :class="[
      'lassox-diagram__CustomScrollBar',
      `lassox-diagram__CustomScrollBar--${axis}`,
    ]"
    :style="[
      axis === 'x' ? {
        left: `${paddingLeft}px`,
        right: `${paddingRight}px`,
      } : {
        top: `${paddingTop}px`,
        bottom: `${paddingBottom}px`,
      },
      !overflowSize ? {
        opacity: '0',
        pointerEvents: 'none',
      } : {},
    ]"
  >
    <div
      ref="thumbEl"
      class="lassox-diagram__CustomScrollBar-thumb"
      @mousedown="onThumbMouseDown"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'

type Axis = 'x' | 'y'

@Component({})

export default class CustomScrollBar extends Vue {
  @Prop({ type: String, required: true })
  readonly axis!: Axis

  @Prop({ type: Number, required: true })
  readonly viewSize!: number

  @Prop({ type: Number, required: true })
  readonly contentSize!: number

  @Prop({ type: Number, required: true })
  readonly scroll!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingTop!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingLeft!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingRight!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingBottom!: number

  draggingThumb = false
  dragStartPos = 0
  dragStartScroll = 0

  get overflowSize () {
    return this.contentSize - this.viewSize
  }

  get viewToContentRatio () {
    return this.viewSize / this.contentSize
  }

  get scrollBarSize () {
    let size = this.viewSize
    if (this.axis === 'x') size -= this.paddingLeft + this.paddingRight
    else size -= this.paddingTop + this.paddingBottom
    return size
  }

  get scrollBarToContentRatio () {
    return this.scrollBarSize / this.contentSize
  }

  get thumbOffset () {
    return this.scroll / this.contentSize
  }

  onThumbMouseDown (e: MouseEvent) {
    e.preventDefault()

    if (this.draggingThumb) {
      window.removeEventListener('mousemove', this.onThumbMouseMove)
      window.removeEventListener('mouseup', this.onThumbMouseUp)
    }

    this.draggingThumb = true
    this.dragStartPos = e[`screen${this.axis === 'x' ? 'X' : 'Y'}` as const]
    this.dragStartScroll = this.scroll

    window.addEventListener('mousemove', this.onThumbMouseMove)
    window.addEventListener('mouseup', this.onThumbMouseUp)
  }

  onThumbMouseMove (e: MouseEvent) {
    e.preventDefault()

    const mousePos = e[`screen${this.axis === 'x' ? 'X' : 'Y'}` as const]
    const mouseDelta = mousePos - this.dragStartPos

    let newScroll = this.dragStartScroll
    newScroll += mouseDelta / this.scrollBarToContentRatio
    newScroll = Math.max(0, newScroll)
    newScroll = Math.min(this.overflowSize, newScroll)

    this.$emit('updateScroll', newScroll)
  }

  onThumbMouseUp (e: MouseEvent) {
    e.preventDefault()

    this.draggingThumb = false
    window.removeEventListener('mousemove', this.onThumbMouseMove)
    window.removeEventListener('mouseup', this.onThumbMouseUp)
  }

  mounted () {
    // const el = this.$el as HTMLElement
    const thumbEl = this.$refs.thumbEl as HTMLElement

    const sizeAttr = this.axis === 'x' ? 'width' : 'height'
    const offsetAttr = this.axis === 'x' ? 'left' : 'top'

    this.$watch(
      () => this.viewToContentRatio,
      () => thumbEl.style[sizeAttr] = `${this.viewToContentRatio * 100}%`,
      { immediate: true },
    )

    this.$watch(
      () => this.thumbOffset,
      () => thumbEl.style[offsetAttr] = `${this.thumbOffset * 100}%`,
      { immediate: true },
    )
  }

  beforeDestroy () {
    window.removeEventListener('mousemove', this.onThumbMouseMove)
    window.removeEventListener('mouseup', this.onThumbMouseUp)
  }
}
</script>

<style lang="scss">
.lassox-diagram__CustomScrollBar {
  position: absolute;
  background-color: rgba(0, 0, 0, 0.125);
  opacity: 1;
  transition: opacity 100ms;

  &--x {
    left: 0;
    right: 0;
    bottom: 0;
    height: 4px;
  }

  &--y {
    top: 0;
    right: 0;
    bottom: 0;
    width: 4px;
  }

  &-thumb {
    position: absolute;
    background-color: rgba(0, 0, 0, 0.25);

    &:hover {
      background-color: rgba(0, 0, 0, 0.5);
    }
  }

  &--x &-thumb {
    top: 0;
    bottom: 0;
  }

  &--y &-thumb {
    left: 0;
    right: 0;
  }
}
</style>
