<template>
  <EditorFields v-if="shownFieldStates.length">
    <EditorField
      v-for="state of shownFieldStates"
      :key="state.field.fullId"
      :id="state.field.fullId"
      :type="state.field.type"
      :title="state.field.title"
      :editable="state.field.editable"
      :formatter="state.field.formatter"
      :value="state.value"
      :errorMessage="state.errorMessage"
      @change="state.onChange"
    />
  </EditorFields>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import EditorFields from './EditorFields.vue'
import EditorField from './EditorField.vue'
import { ContextItem, EntityType, RelationType } from '../diagram'
import _set from 'lodash.set'

@Component({
  components: {
    EditorFields,
    EditorField,
  },
})

export default class DataCreator extends Vue {
  @Prop({ type: Object, required: true })
  readonly type!: EntityType | RelationType

  @Model('change', { type: Object, default: () => ({}) })
  readonly data!: Record<string, any>

  get fieldStates () {
    const { type } = this

    return Vue.observable(type.fields.map(field => {
      let value = field.getValue(this.data)

      if (!field.editable && field.formatter && field.type === 'text') {
        value = field.formatter(value)
      }

      const state = {
        field,
        get show () { return field[type instanceof EntityType ? 'isEntityLabel' : 'isRelationLabel'] || !!state.errorMessage },
        value,
        errorMessage: '',
        onChange: (value: any) => {
          state.value = value
          if (field.dataKey) _set(this.data, field.dataKey, value)
          this.$emit('change', this.data)
        },
      }

      return state
    }))
  }

  get shownFieldStates () {
    return Vue.observable(this.fieldStates.filter(state => state.show))
  }

  validate (contextItem: ContextItem) {
    let error = false

    for (const field of this.fieldStates) {
      field.errorMessage = ''

      const result = field.field.validator?.(field.value, contextItem) ?? true
      if (result === true) continue

      error = true
      field.errorMessage = result.error
    }

    return !error
  }
}
</script>
