<template>
  <div
    :class="[
      'lassox-diagram__TextField',
      disabled ? 'lassox-diagram__TextField--is-disabled' : '',
      error ? 'lassox-diagram__TextField--has-error' : '',
      leadingIcon ? 'lassox-diagram__TextField--has-leading-icon' : '',
      error || trailingIcon ? 'lassox-diagram__TextField--has-trailing-icon' : '',
      focused && 'lassox-diagram__TextField--is-focused',
    ]"
  >
    <div class="lassox-diagram__TextField-outline" />

    <input
      ref="inputEl"
      class="lassox-diagram__TextField-input"
      :name="name"
      :type="type"
      :disabled="disabled"
      :autocomplete="autocomplete"
      :value="value"
      v-on="{
        ...$listeners,
        focus: [
          e => {
            focused = true
            if ($listeners.focus) $listeners.focus(e)
          }
        ],
        blur: [
          e => {
            focused = false
            if ($listeners.blur) $listeners.blur(e)
          }
        ],
      }"
    >

    <Icon
      v-if="leadingIcon"
      class="lassox-diagram__TextField-leading-icon"
      :icon="leadingIcon"
    />

    <template v-if="error || trailingIcon">
      <Icon
        v-if="error || !onClickTrailingIcon"
        class="lassox-diagram__TextField-trailing-icon"
        :icon="error ? 'error' : trailingIcon"
      />

      <IconButton
        v-else
        class="lassox-diagram__TextField-trailing-icon"
        :icon="trailingIcon"
        @click="() => onClickTrailingIcon()"
      />
    </template>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model, Ref } from 'vue-property-decorator'
import Icon from './Icon.vue'
import IconButton from './IconButton.vue'

@Component({
  components: {
    Icon,
    IconButton,
  },
})

export default class TextField extends Vue {
  @Prop(Boolean)
  readonly autofocus!: boolean

  @Prop(String)
  readonly name?: string

  @Prop({ type: String, default: 'text' })
  readonly type!: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Prop(Boolean)
  readonly error!: boolean

  @Prop(String)
  readonly autocomplete?: string

  @Prop(String)
  readonly leadingIcon?: string

  @Prop(String)
  readonly trailingIcon?: string

  @Prop(Function)
  readonly onClickTrailingIcon?: () => void

  @Model('input')
  readonly value?: any

  @Ref()
  readonly inputEl!: HTMLInputElement

  focused = false

  mounted () {
    if (this.autofocus) this.inputEl.focus()
  }
}
</script>

<style lang="scss">
.lassox-diagram__TextField {
  position: relative;
  display: flex;
  background-color: white;
  border-radius: 2px;
  opacity: 1;
  transition: opacity 100ms;

  &-outline {
    pointer-events: none;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    color: rgba(black, 0.12);
    border-radius: inherit;
    box-shadow: inset 0 0 0 1px;
    transition: box-shadow 100ms;
  }

  &-leading-icon,
  &-trailing-icon {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
  }

  &-leading-icon {
    left: 9px;
    pointer-events: none;
  }

  &-trailing-icon {
    right: 9px;
  }

  &-input {
    appearance: none;
    display: block;
    box-sizing: border-box;
    width: 100%;
    min-height: 36px;
    padding: 10px 12px;
    border: 0;
    margin: 0;
    font: inherit;
    font-size: 12px;
    line-height: 16px;
    color: inherit;
    background-color: transparent;

    &:focus {
      outline: none;
    }

    &::-ms-clear {
      display: none;
    }
  }

  &--is-disabled {
    opacity: 0.5;
  }

  &--has-leading-icon &-input {
    padding-left: 36px;
  }

  &--has-trailing-icon &-input {
    padding-right: 36px;
  }

  &--is-focused &-outline {
    color: rgba(black, 0.6);
    box-shadow: inset 0 0 0 2px;
  }

  &--has-error,
  &--has-error &-outline,
  &--has-error &-leading-icon,
  &--has-error &-trailing-icon {
    color: #EF4444;
  }
}
</style>
